// Original practice material grounded in the January 2026 GH-900 blueprint.
// AI self-reviewed; Preview only. Human review is still required.
export const questions = [
  {id:"ghf-001",domain:"Understand Git and GitHub basics",prompt:"A policy team needs to explain how a document changed over several months. What does version control provide?",choices:["A recorded history of changes","A guarantee that every change is correct","Automatic legal approval","A replacement for document review"],correct:0,explanations:["Version control records changes that can be inspected over time.","Recording a change does not validate its correctness.","Legal approval requires a separate process.","Review remains necessary even with recorded history."],concept:"Version control purpose",hints:["What evidence would explain past edits?","Distinguish recording work from approving work."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-002",domain:"Understand Git and GitHub basics",prompt:"Which statement correctly distinguishes Git from GitHub?",choices:["Git requires GitHub to store commits","Git tracks versions; GitHub hosts repositories and collaboration","GitHub is the local staging area","Git is only a graphical interface for GitHub"],correct:1,explanations:["Git can manage repositories without GitHub.","Git is version control software; GitHub adds hosting and collaboration.","The staging area belongs to a local Git repository.","Git has its own command-line tools and data model."],concept:"Git versus GitHub",hints:["Which component can operate offline?","Separate version tracking from hosted collaboration."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-003",domain:"Understand Git and GitHub basics",prompt:"A developer wants the project files and their Git history on a laptop. Which operation should they use?",choices:["Star the repository","Download a source ZIP","Clone the repository","Watch the repository"],correct:2,explanations:["Starring bookmarks a repository without copying its history.","A source ZIP does not include the Git repository history.","Cloning creates a local repository with Git history.","Watching configures notifications rather than a local copy."],concept:"Cloning",hints:["Does the result need version metadata?","Compare an archive with a working repository."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/cloning-a-repository"},
  {id:"ghf-004",domain:"Understand Git and GitHub basics",prompt:"An author has edited several tracked files but wants the next commit to include only two. What should they do first?",choices:["Push the working tree directly","Commit all tracked modifications with no selection","Fetch the remote","Stage the selected changes"],correct:3,explanations:["Push transfers existing commits rather than selecting working-tree edits.","Committing all modifications would include the unwanted files.","Fetch updates remote-tracking information rather than the index.","Staging selects content for the next commit."],concept:"Staging area",hints:["How is the next snapshot assembled?","Which action occurs before recording a commit?"],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-005",domain:"Understand Git and GitHub basics",prompt:"What is a Git commit best understood as?",choices:["A recorded snapshot with identifying metadata","A live copy of every current uncommitted edit","A request to integrate changes that has not recorded them","A network connection that keeps two folders synchronized"],correct:0,explanations:["A commit records a snapshot and metadata such as author and message.","Uncommitted edits are not automatically part of recorded history.","A commit records work; a pull request proposes integrating recorded work.","Commits persist independently of a network connection."],concept:"Commits",hints:["What remains after the editor closes?","Think about an identifiable point in history."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-006",domain:"Understand Git and GitHub basics",prompt:"A designer wants to experiment without changing the default branch. Which Git concept supports this?",choices:["A milestone","A separate branch","A repository topic","A notification filter"],correct:1,explanations:["Milestones group work items rather than isolate file changes.","A branch provides a separate line of work.","Topics improve repository discovery.","Notification filters select messages, not versions."],concept:"Branch isolation",hints:["Where can an alternative line of work live?","Separate work isolation from task tracking."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-007",domain:"Understand Git and GitHub basics",prompt:"A local commit exists on a feature branch, but teammates cannot see it on GitHub. Which action normally shares that commit?",choices:["Stage its files again","Fetch the remote branch","Push the branch to the remote","Create another local branch at the commit"],correct:2,explanations:["Staging does not transfer existing commits.","Fetch retrieves remote history rather than publishes local history.","Push sends local commits to the remote branch.","Another local reference does not transmit the commit."],concept:"Push",hints:["Which direction must the history travel?","Is the commit already recorded locally?"],source:"https://docs.github.com/en/get-started/using-git/pushing-commits-to-a-remote-repository"},
  {id:"ghf-008",domain:"Understand Git and GitHub basics",prompt:"You want to retrieve remote changes for inspection without integrating them into your current branch. Which operation fits?",choices:["Commit","Push","Merge","Fetch"],correct:3,explanations:["Commit records local staged changes.","Push publishes local history.","Merge integrates histories into a branch.","Fetch retrieves remote history without merging it into the current branch."],concept:"Fetch",hints:["Separate retrieval from integration.","Which action leaves your current line of work unchanged?"],source:"https://docs.github.com/en/get-started/using-git/getting-changes-from-a-remote-repository"},
  {id:"ghf-009",domain:"Understand Git and GitHub basics",prompt:"How does git pull differ from git fetch in an ordinary branch workflow?",choices:["Pull retrieves changes and then integrates them","Pull only uploads local commits","Pull creates a GitHub account","Pull deletes the remote history"],correct:0,explanations:["Pull fetches and integrates, using merge or rebase according to configuration.","Uploading local commits is the role of push.","Account creation is unrelated to Git pull.","Pull does not delete remote history."],concept:"Pull versus fetch",hints:["Which operation goes beyond retrieval?","Account for configurable integration behavior."],source:"https://docs.github.com/en/get-started/using-git/getting-changes-from-a-remote-repository"},
  {id:"ghf-010",domain:"Understand Git and GitHub basics",prompt:"Two branches edit the same passage differently and Git cannot combine them automatically. What is needed?",choices:["Another fetch without changing either passage","A merge conflict resolution","Only a new commit message for the unchanged conflict","Renaming the source branch"],correct:1,explanations:["Retrieving the same histories again does not reconcile their edits.","A person must reconcile conflicting changes before the merge can finish.","Changing a message alone leaves the incompatible content unresolved.","Renaming a branch does not reconcile its content."],concept:"Merge conflicts",hints:["Can software infer the intended wording?","Focus on incompatible edits rather than branch metadata."],source:"https://docs.github.com/en/pull-requests/reference/merge-conflicts"},
  {id:"ghf-011",domain:"Understand Git and GitHub basics",prompt:"A team wants to undo a published change while preserving an auditable shared history. Which approach is most appropriate?",choices:["Reset the shared branch to an earlier commit and force-push","Delete the local branch containing the change","Create a revert commit","Add the changed files to .gitignore"],correct:2,explanations:["Resetting and force-pushing rewrites the shared branch history rather than recording a reversal.","Deleting a local branch does not reverse changes already integrated remotely.","Revert records a new commit that reverses earlier changes.","Ignore rules do not undo tracked, committed changes."],concept:"Reverting shared changes",hints:["Must existing shared history remain intact?","Consider recording the reversal as new work."],source:"https://docs.github.com/en/pull-requests/how-tos/merge-and-close-pull-requests/reverting-a-pull-request"},
  {id:"ghf-012",domain:"Understand Git and GitHub basics",prompt:"Which message best describes an isolated commit that corrects a broken documentation link?",choices:["Changes","Update things","Final version","Fix installation guide link to setup instructions"],correct:3,explanations:["Changes gives no useful description of intent.","Update things does not identify the affected behavior.","Final version does not explain what changed.","The message identifies both the affected material and the correction."],concept:"Descriptive commit messages",hints:["What would help a future maintainer?","Prefer a concrete change over a vague status."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-013",domain:"Understand Git and GitHub basics",prompt:"Why keep an unrelated UI redesign and a spelling correction on separate branches?",choices:["They can be reviewed and delivered independently","Git forbids multiple files on one branch","Each branch must have its own organization","Separate branches remove the need for tests"],correct:0,explanations:["Independent branches reduce coupling between unrelated work.","Branches can contain changes to many files.","Branches belong to a repository, not separate organizations.","Testing remains necessary on separate branches."],concept:"Focused branches",hints:["What if one change is delayed?","Consider the reviewer’s scope."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-014",domain:"Understand Git and GitHub basics",prompt:"In GitHub flow, when should work on a feature branch become part of the default branch?",choices:["As soon as the branch is named","When its pull request is merged after required checks and review","When the author stars the repository","Whenever a teammate clones the repository"],correct:1,explanations:["Naming a branch does not integrate its contents.","Merging integrates the work, subject to repository requirements.","Stars do not merge changes.","Cloning copies history without modifying the source branch."],concept:"GitHub flow integration",hints:["What action integrates the proposed change?","Which safeguards may block that action?"],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-015",domain:"Understand Git and GitHub basics",prompt:"An author pushes another commit to the same head branch of an open pull request. What happens?",choices:["The pull request must be recreated to include it","The new commit is automatically merged into the base","The pull request includes the new commit","The new commit remains excluded until the title changes"],correct:2,explanations:["The existing pull request tracks its head branch.","Updating the proposal does not automatically integrate it.","New commits on the head branch update the existing proposal.","Changing the title is not required to include new head-branch commits."],concept:"Iterating on a pull request",hints:["Does the proposal track a frozen ZIP?","Think about the relationship to the branch."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-016",domain:"Understand Git and GitHub basics",prompt:"After a feature is merged, why might the team delete its feature branch?",choices:["To erase the pull request conversation","To delete every local copy of that branch automatically","To remove the merged changes from the default branch","To signal completion and reduce stale branch clutter"],correct:3,explanations:["The pull request conversation remains available.","Remote branch deletion does not remove everyone’s local branch automatically.","Merged changes remain in the destination branch.","Removing the completed branch helps prevent accidental reuse."],concept:"Branch cleanup",hints:["What has already been preserved by the merge?","Distinguish a branch reference from merged content."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-017",domain:"Understand Git and GitHub basics",prompt:"A repository has a local remote named origin. What is origin?",choices:["A conventional alias for a remote repository URL","A protected branch required by Git","A GitHub organization role","A license automatically applied to code"],correct:0,explanations:["Origin is a common remote name, not a mandatory server type.","Remote names and branch names are different concepts.","It is not an access role.","Remote aliases do not determine licensing."],concept:"Remote names",hints:["What does git remote describe?","Is this name a location alias or a version?"],source:"https://docs.github.com/en/get-started/git-basics/about-remote-repositories"},
  {id:"ghf-018",domain:"Understand Git and GitHub basics",prompt:"Which property makes Git a distributed version control system?",choices:["Every edit requires an internet connection","Local repositories can contain history and support local commits","Only one central server can record changes","Each file must be owned by a different person"],correct:1,explanations:["Local Git operations can work offline.","Git repositories support history and commits without contacting GitHub.","Git does not reserve commit creation to one central server.","File ownership is unrelated to distributed version control."],concept:"Distributed version control",hints:["Where can history be recorded?","Would local work stop if GitHub were unreachable?"],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-019",domain:"Understand Git and GitHub basics",prompt:"Which command reports modified files and whether changes are staged?",choices:["git push","git clone","git status","git remote add"],correct:2,explanations:["Push transfers commits.","Clone creates a repository copy.","Status summarizes working tree and staging state.","Remote add configures a remote URL."],concept:"Working tree status",hints:["Which command observes rather than transfers?","Look for staging information."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-020",domain:"Understand Git and GitHub basics",prompt:"A maintainer wants to inspect line-level changes before committing. Which command is designed for this comparison?",choices:["git init","git remote","git branch","git diff"],correct:3,explanations:["Init creates repository metadata.","Remote manages configured repository locations.","Branch manages or lists branch references.","Diff displays differences between file versions or states."],concept:"Diff inspection",hints:["What output would reveal added and removed lines?","Distinguish a comparison from a branch list."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-021",domain:"Understand Git and GitHub basics",prompt:"Which action starts Git tracking in an existing local folder that is not yet a repository?",choices:["Run git init in that folder","Run git fetch before creating any repository metadata","Create a .gitignore file without initializing Git","Only rename the folder to match a GitHub repository"],correct:0,explanations:["Git init creates the local Git repository metadata.","Fetch operates on an existing repository rather than initializing this folder.","An ignore file alone does not create a repository.","A folder name does not initialize version control."],concept:"Repository initialization",hints:["Must this action contact GitHub?","Which action creates local version-control metadata?"],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-022",domain:"Understand Git and GitHub basics",prompt:"What is the working tree in a local Git repository?",choices:["Only the changes selected in the index","The checked-out files being worked on","The remote-tracking branch references only","The entire commit graph without checked-out files"],correct:1,explanations:["The index holds selected content for the next commit, not the whole working tree.","The working tree contains the files checked out for editing.","Remote-tracking references identify retrieved remote positions rather than editable files.","Recorded history is distinct from the current checked-out files."],concept:"Working tree",hints:["Where do ordinary file edits occur?","Separate editable files from the index and recorded history."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-023",domain:"Understand Git and GitHub basics",prompt:"A team wants a recognizable reference to the commit used for a release. Which Git feature fits?",choices:["An assignee","A reaction","A tag","A saved reply"],correct:2,explanations:["Assignees identify responsibility for work items.","Reactions communicate feedback.","A tag marks a particular point in repository history.","Saved replies reuse comment text."],concept:"Tags",hints:["What identifies a historical version?","Separate version markers from collaboration metadata."],source:"https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases"},
  {id:"ghf-024",domain:"Understand Git and GitHub basics",prompt:"A colleague has a commit identifier and wants to inspect that exact change later. Why is the identifier useful?",choices:["It always points to the latest state of the default branch","It refers to every commit by the same author","It changes whenever another branch advances","It identifies a particular commit"],correct:3,explanations:["A specific commit identifier does not move with the default branch.","Different commits by one author have distinct identities.","Advancing another branch does not change an existing commit identifier.","The identifier lets people reference a specific recorded revision."],concept:"Commit identifiers",hints:["Is this a fixed revision or a moving branch?","Think about locating a precise point in history."],source:"https://docs.github.com/en/pull-requests/reference/commits"},
  {id:"ghf-025",domain:"Understand Git and GitHub basics",prompt:"What is a repository’s default branch primarily used for?",choices:["The normal base for new pull requests and repository browsing","A fixed reference to the latest published release","A personal scratch branch unique to each visitor","A branch that always rejects commits regardless of settings"],correct:0,explanations:["The default branch is the usual starting view and pull request base.","The default branch can advance independently of published releases.","The default is a repository setting, not a separate scratch branch per visitor.","Default status alone does not impose a no-commits rule."],concept:"Default branch",hints:["What version do visitors normally see first?","Consider the initial target for a proposed change."],source:"https://docs.github.com/en/pull-requests/reference/branches"},
  {id:"ghf-026",domain:"Understand Git and GitHub basics",prompt:"A new contributor confuses cloning with forking. Which distinction is correct?",choices:["Cloning grants upstream write access; forking only grants read access","Forking creates a related repository on GitHub; cloning creates a local copy","Forking removes history; cloning retains only the latest files","Cloning automatically creates a fork under the user’s account"],correct:1,explanations:["Neither operation grants direct upstream write access.","A fork is a separate related hosted repository; a clone is local.","Forks retain upstream history, and ordinary clones include Git history.","A clone does not automatically create a hosted fork."],concept:"Clone versus fork",hints:["Where does each resulting copy live?","Does a separate hosted namespace matter?"],source:"https://docs.github.com/en/get-started/learning-about-github/github-glossary"},
  {id:"ghf-027",domain:"Understand Git and GitHub basics",prompt:"A laptop is offline. Which activity can ordinarily still be performed in an existing local Git repository?",choices:["Fetch new GitHub commits","Read newly posted GitHub issues","Create a local commit","Push a branch to GitHub"],correct:2,explanations:["Fetching from GitHub requires network access.","New hosted issues cannot be retrieved offline.","Local commits do not require contacting GitHub.","Pushing to GitHub requires a network connection."],concept:"Offline Git",hints:["Which operation uses only local data?","Separate Git operations from server communication."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-028",domain:"Understand Git and GitHub basics",prompt:"What is the main effect of merging one branch into another?",choices:["It only downloads changes without integrating them","It switches the checkout without combining any work","It always discards every destination-only change","It integrates changes from the source branch"],correct:3,explanations:["Retrieval without integration describes fetch.","Switching branches selects work rather than merges it.","Merge combines histories and does not inherently discard all destination-only work.","Merge combines the relevant lines of development."],concept:"Merging",hints:["Which part of the project is combined?","Separate retrieval and checkout from integration."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-029",domain:"Understand Git and GitHub basics",prompt:"Which GitHub account type is designed to represent one person’s identity?",choices:["A personal account","An organization account shared as a login","A repository branch","An enterprise policy"],correct:0,explanations:["A personal account represents an individual user.","Organizations are managed through members’ personal identities rather than a shared organization login.","A branch is a version-control reference.","Policies are settings, not individual identities."],concept:"Personal accounts",hints:["How is individual activity attributed?","Separate a person from a shared ownership container."],source:"https://docs.github.com/en/get-started/learning-about-github/types-of-github-accounts"},
  {id:"ghf-030",domain:"Understand Git and GitHub basics",prompt:"A company wants shared repository ownership with teams and member permissions. Which structure is appropriate?",choices:["A single employee’s gist","A GitHub organization","A commit tag","A Markdown task list"],correct:1,explanations:["A personal gist is not an organizational ownership and team structure.","Organizations support shared ownership and managed collaboration.","A tag identifies a version.","A task list cannot administer repository access."],concept:"Organizations",hints:["Who should own repositories beyond one employee?","Which structure supports teams?"],source:"https://docs.github.com/en/get-started/learning-about-github/types-of-github-accounts"},
  {id:"ghf-031",domain:"Understand Git and GitHub basics",prompt:"What does an enterprise account help a company manage across multiple GitHub organizations?",choices:["A single combined Git history for every repository","One shared login used by all employees","Shared policies and centralized administration","Automatic merging of every organization’s default branches"],correct:2,explanations:["Repositories retain their own histories rather than become one Git repository.","An enterprise account does not replace individually attributable user identities.","Enterprise accounts provide an administrative layer across organizations.","Enterprise grouping does not automatically combine repository branches."],concept:"Enterprise accounts",hints:["What sits above individual organizations?","Think about governance across organizational boundaries."],source:"https://docs.github.com/en/get-started/learning-about-github/types-of-github-accounts"},
  {id:"ghf-032",domain:"Understand Git and GitHub basics",prompt:"Which deployment model is GitHub Enterprise Server?",choices:["Only a personal GitHub.com account with a larger quota","Only a GitHub-operated organization on GitHub.com","A local Git client with no collaboration server","A GitHub instance operated on infrastructure you control"],correct:3,explanations:["Enterprise Server is a separate deployment rather than a larger personal quota.","That describes a hosted organization rather than the Server deployment model.","Enterprise Server provides a collaboration service, not just a local client.","Enterprise Server is self-hosted on customer-controlled infrastructure."],concept:"Cloud versus Server",hints:["Who operates the hosting infrastructure?","Separate deployment model from account identity."],source:"https://docs.github.com/en/get-started/learning-about-github/githubs-plans"},
  {id:"ghf-033",domain:"Understand Git and GitHub basics",prompt:"A contributor prefers visual local Git operations instead of typing commands. Which GitHub tool is the closest fit?",choices:["GitHub Desktop","GitHub Pages","GitHub Sponsors","GitHub Discussions"],correct:0,explanations:["Desktop provides a graphical interface for local repository workflows.","Pages publishes websites.","Sponsors facilitates financial support.","Discussions hosts conversations."],concept:"GitHub Desktop",hints:["Does the tool manage files on the computer?","Look for a graphical Git workflow."],source:"https://docs.github.com/en/desktop/overview/about-github-desktop"},
  {id:"ghf-034",domain:"Understand Git and GitHub basics",prompt:"During a commute, a maintainer wants an app designed for triaging GitHub notifications and responding to issues from a phone. Which tool fits?",choices:["GitHub Desktop","GitHub Mobile","GitHub CLI","The github.dev source editor"],correct:1,explanations:["Desktop is designed for graphical repository workflows on a computer.","Mobile supports GitHub collaboration from a phone.","CLI targets terminal-based workflows rather than a phone collaboration app.","Github.dev is a source editor rather than the intended mobile notification app."],concept:"GitHub Mobile",hints:["What device and activities are involved?","Which interface is designed for that form factor?"],source:"https://docs.github.com/en/get-started/using-github/github-mobile"},
  {id:"ghf-035",domain:"Understand Git and GitHub basics",prompt:"A shell script needs to create GitHub issues using a supported command-line client. Which tool is appropriate?",choices:["GitHub Pages","GitHub Desktop only","GitHub CLI","A Markdown renderer"],correct:2,explanations:["Pages serves static website content.","Desktop is graphical rather than a shell-oriented GitHub client.","GitHub CLI exposes GitHub workflows through commands such as gh issue.","Rendering Markdown does not create hosted issues."],concept:"GitHub CLI",hints:["Does the workflow require commands in a shell?","Is this a GitHub service action or just local version control?"],source:"https://docs.github.com/en/github-cli/github-cli/about-github-cli"},
  {id:"ghf-036",domain:"Understand Git and GitHub basics",prompt:"Which task is a GitHub collaboration feature rather than a core Git command’s responsibility?",choices:["Recording a local commit","Creating a branch","Comparing file versions","Requesting review on a hosted pull request"],correct:3,explanations:["Git records commits directly.","Git manages branches directly.","Git can compare versions directly.","Hosted review requests are part of GitHub’s collaboration layer."],concept:"GitHub collaboration layer",hints:["Which activity involves hosted review participants?","Separate repository mechanics from the platform workflow."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-037",domain:"Understand Git and GitHub basics",prompt:"An issue needs a top-level Markdown heading. Which text uses the appropriate syntax?",choices:["# Deployment notes","[Deployment notes]","@Deployment notes","`Deployment notes`"],correct:0,explanations:["A leading hash followed by a space creates a heading.","Brackets alone do not create a heading.","The at sign is used for mentions in appropriate contexts.","Backticks format inline code."],concept:"Markdown headings",hints:["Which syntax indicates document hierarchy?","Distinguish a heading from inline emphasis."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-038",domain:"Understand Git and GitHub basics",prompt:"Which Markdown snippet displays setup as inline code in a sentence?",choices:["**setup**","`setup`","[setup](https://example.com)","## setup"],correct:1,explanations:["Double asterisks produce bold text.","Backticks mark inline code.","This syntax creates a hyperlink.","Hash marks create a heading."],concept:"Inline code formatting",hints:["Which formatting suits identifiers and commands?","The text should stay within the sentence."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-039",domain:"Understand Git and GitHub basics",prompt:"Which Markdown creates a link with the visible label Guide?",choices:["(Guide)[https://docs.github.com]","<Guide>https://docs.github.com","[Guide](https://docs.github.com)","# Guide https://docs.github.com"],correct:2,explanations:["The label and URL delimiters are reversed.","This does not use labeled-link syntax.","Square brackets hold the label and parentheses hold the target.","This creates heading text rather than the requested labeled link."],concept:"Markdown links",hints:["Where do the label and destination belong?","Look for paired delimiters around each part."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-040",domain:"Understand Git and GitHub basics",prompt:"A bug report includes a multiline stack trace. Which formatting best preserves its code layout?",choices:["An ordinary paragraph","A bold paragraph","A single inline-code span for the entire trace","A fenced code block"],correct:3,explanations:["Ordinary paragraph rendering does not preserve code layout as a block.","Bold text does not provide multiline code formatting.","Inline code is intended for short text within a line rather than a multiline trace.","A fenced code block preserves a multiline code presentation."],concept:"Code blocks",hints:["What preserves line breaks and indentation?","Choose block-level rather than inline formatting."],source:"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-and-highlighting-code-blocks"},
  {id:"ghf-041",domain:"Understand Git and GitHub basics",prompt:"A release checklist needs an unchecked task item in Markdown. Which syntax is appropriate?",choices:["- [ ] Verify migration","[Verify migration](pending)","@Verify migration","# [Verify migration]"],correct:0,explanations:["A list marker followed by an empty checkbox creates an unchecked task.","This is link syntax, not a checkbox.","The at sign does not create a task item.","A heading does not create an interactive task checkbox."],concept:"Markdown task lists",hints:["What combines a list item and a checkbox?","Should the box already contain a completion mark?"],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-042",domain:"Understand Git and GitHub basics",prompt:"A comment should notify a teammate named river about a question. Which text uses GitHub mention syntax?",choices:["#river","@river","!river","`river`"],correct:1,explanations:["The hash sign is not the user mention prefix.","The at sign followed by a username creates a mention.","An exclamation mark is not user mention syntax.","Inline code formatting does not mention a user."],concept:"Mentions",hints:["Which prefix identifies a person in a conversation?","Formatting a name is not the same as addressing someone."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-043",domain:"Understand Git and GitHub basics",prompt:"Within a repository issue, an author writes #84 to reference another issue in the same repository. What does GitHub normally provide?",choices:["Automatic closure of issue 84 from the reference alone","A duplicate of issue 84","A linked reference to that issue","A reference to commit 84 rather than the issue"],correct:2,explanations:["A bare reference is not an issue-closing keyword workflow.","Referencing an issue does not duplicate it.","GitHub autolinks issue-number references in supported conversation contexts.","The hash-number form identifies an issue or pull request in this context."],concept:"Issue references",hints:["Is this navigation or mutation?","What context supplies the repository name?"],source:"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/autolinked-references-and-urls"},
  {id:"ghf-044",domain:"Understand Git and GitHub basics",prompt:"A reviewer wants to quote an earlier sentence before responding. Which Markdown prefix creates a blockquote?",choices:["@","!","- [ ]",">"],correct:3,explanations:["The at sign is used for mentions.","An exclamation mark participates in image syntax, not blockquotes.","This creates an unchecked task item.","A greater-than prefix creates quoted text."],concept:"Blockquotes",hints:["How can quoted material be visually separated?","Choose the syntax for quoting rather than task tracking."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-045",domain:"Understand Git and GitHub basics",prompt:"A root README needs a link to docs/setup.md that follows the currently browsed branch. What is the best choice?",choices:["A relative link to docs/setup.md","An absolute link pinned to one commit’s setup.md","An absolute link always targeting main’s setup.md","A link to the repository homepage rather than the file"],correct:0,explanations:["GitHub resolves this relative link using the currently browsed branch.","A commit-pinned link intentionally stays at a fixed revision.","A main-pinned link does not follow other browsed branches.","The homepage does not directly target the setup document."],concept:"Relative documentation links",hints:["Should the destination follow the current branch?","Consider how the repository location supplies context."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-046",domain:"Understand Git and GitHub basics",prompt:"Which Markdown snippet renders the word urgent in bold?",choices:["`urgent`","**urgent**","> urgent","[urgent]"],correct:1,explanations:["Backticks render inline code.","Double asterisks apply bold styling.","A greater-than prefix creates a blockquote.","Brackets alone do not apply bold styling."],concept:"Text emphasis",hints:["Which delimiter surrounds emphasized text?","Exclude code and quotation formatting."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-047",domain:"Understand Git and GitHub basics",prompt:"A writer wants a bulleted list of prerequisites without implying an execution order. Which Markdown structure fits?",choices:["A numbered list","A fenced code block","An unordered list","A heading for every word"],correct:2,explanations:["Numbered lists communicate ordering.","Code blocks present literal code-like content.","Unordered lists present items without a numbered sequence.","Headings establish sections rather than a compact list."],concept:"Unordered lists",hints:["Is sequence meaningful here?","Choose a list structure rather than code formatting."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-048",domain:"Understand Git and GitHub basics",prompt:"A documentation contributor adds alt text to a Markdown image. What is its primary purpose?",choices:["To specify the image file’s storage path","To provide only a mouse-hover title","To set the image’s display dimensions","To provide a textual description for accessibility"],correct:3,explanations:["The image URL or path is a separate part of Markdown image syntax.","Alt text is not merely a hover-title field.","Alt text describes content rather than specifies width and height.","Alt text helps convey image meaning when visual content cannot be perceived."],concept:"Accessible image descriptions",hints:["Who might not be able to see the image?","Separate descriptive content from image placement."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-049",domain:"Understand Git and GitHub basics",prompt:"A team chooses GitHub flow for a non-code handbook. Is that a suitable use?",choices:["Yes; branch-based review can apply to documentation too","No; only compiled programs can use branches","No; Markdown cannot be committed","Only if every document becomes an issue"],correct:0,explanations:["GitHub flow supports collaborative changes beyond application code.","Branches are not limited to compiled languages.","Markdown files can be versioned normally.","Documents can remain files while issues track related work."],concept:"GitHub flow beyond code",hints:["Does version control depend on compilation?","What kinds of files benefit from review?"],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-050",domain:"Understand Git and GitHub basics",prompt:"Before opening a pull request for a branch, what should its author include to help reviewers understand the proposal?",choices:["Only the branch name with no further context","A summary of the changes and the problem they solve","Only the word updated as the entire description","Only an assertion that no review is necessary"],correct:1,explanations:["A branch name alone may not explain the reason and scope.","A concise summary and rationale provide review context.","A generic status word does not describe the work.","An assertion that review is unnecessary does not provide review evidence."],concept:"Change communication",hints:["What would a reviewer need before reading the diff?","Explain intent as well as content."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-051",domain:"Understand Git and GitHub basics",prompt:"Why is a commit with one coherent change generally easier to maintain than a commit mixing unrelated changes?",choices:["It never needs review","It cannot introduce a bug","It can be understood and reverted more selectively","It makes branch protection unnecessary"],correct:2,explanations:["Focused commits still need review.","Coherence does not guarantee correctness.","An isolated change is easier to inspect or reverse without affecting unrelated work.","Branch protections serve a separate governance purpose."],concept:"Atomic changes",hints:["What if just one part must be undone?","Think about future diagnosis."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-052",domain:"Understand Git and GitHub basics",prompt:"A branch named fix-search-timeout is preferred over work for an active task. Why?",choices:["Its name enforces passing tests","Its name grants repository access","Its name closes all related issues","Its name communicates the purpose of ongoing work"],correct:3,explanations:["Branch names do not enforce tests.","Access comes from permissions, not names.","Issue closure requires separate links and qualifying events.","A descriptive branch name helps collaborators recognize the work."],concept:"Branch naming",hints:["What can a teammate infer from the branch list?","Names communicate but do not enforce behavior."],source:"https://docs.github.com/en/get-started/using-github/github-flow"},
  {id:"ghf-053",domain:"Understand Git and GitHub basics",prompt:"A contributor runs git add on a file. What has happened at that point?",choices:["The file’s selected content is staged for a future commit","The file has necessarily been uploaded to GitHub","A new commit has necessarily been recorded","All later edits to that file will automatically enter the next commit"],correct:0,explanations:["Git add places content in the index for the next commit.","Staging alone does not contact GitHub.","Recording the snapshot still requires a commit operation.","Edits made after staging require staging again to update the selected content."],concept:"Staging versus publishing",hints:["Which local state changed?","Has history been recorded or transmitted yet?"],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-054",domain:"Understand Git and GitHub basics",prompt:"A team sees a pull request as a request to download files. What is the better description?",choices:["A backup copy with no discussion","A proposal to merge changes between branches","A replacement for a Git commit","An account permission request"],correct:1,explanations:["Pull requests include review and discussion, not just backup content.","A pull request proposes branch changes for review and integration.","Commits remain the underlying recorded changes.","Repository access is administered separately."],concept:"Pull request fundamentals",hints:["What is being proposed to the receiving branch?","Consider review before integration."],source:"https://docs.github.com/en/pull-requests/reference/pull-requests"},
  {id:"ghf-055",domain:"Understand Git and GitHub basics",prompt:"A user changes the URL associated with a local remote. What does this primarily change?",choices:["The contents of every previous commit","Which branch is currently checked out","Where subsequent remote operations connect","Which file changes are staged"],correct:2,explanations:["Remote configuration does not rewrite commit content.","Changing the URL does not switch the active branch.","The configured remote URL determines the remote destination.","The index is separate from remote connection configuration."],concept:"Remote URLs",hints:["Is this history editing or connection configuration?","Which endpoint will a later fetch use?"],source:"https://docs.github.com/en/get-started/git-basics/managing-remote-repositories"},
  {id:"ghf-056",domain:"Understand Git and GitHub basics",prompt:"Two contributors use different supported interfaces, one GitHub Desktop and one Git commands. Can they collaborate in the same GitHub repository?",choices:["No; each interface requires a different history format","No; Desktop repositories cannot have branches","Only if the repository contains no source code","Yes; both interfaces work with Git repositories"],correct:3,explanations:["These interfaces use compatible Git repository history.","Desktop supports branch workflows.","The repository’s content type does not impose this limitation.","Collaborators can use different Git-compatible interfaces."],concept:"Tool interoperability",hints:["Does the interface change the underlying version-control system?","Separate personal tool choice from shared repository history."],source:"https://docs.github.com/en/get-started/using-github/connecting-to-github"},
  {id:"ghf-057",domain:"Understand Git and GitHub basics",prompt:"Which statement about GitHub organization membership is correct?",choices:["People access organizations through their own accounts","Every member must use one shared organization password","Joining an organization deletes personal repositories","Organization membership creates a local Git branch"],correct:0,explanations:["Individual accounts are granted membership and roles.","Sharing credentials undermines individual identity and is not how organizations work.","Personal repositories are not deleted by membership.","Membership is account administration, not branch creation."],concept:"Individual identity in organizations",hints:["How should actions remain attributable?","Separate membership from sharing credentials."],source:"https://docs.github.com/en/get-started/learning-about-github/types-of-github-accounts"},
  {id:"ghf-058",domain:"Understand Git and GitHub basics",prompt:"Why might a company choose GitHub Enterprise Cloud rather than GitHub Enterprise Server?",choices:["Cloud removes the need to manage repository permissions","GitHub operates the hosted service rather than the company operating a server instance","Cloud prevents all merge conflicts","Cloud makes every repository open source"],correct:1,explanations:["Permissions remain important on either deployment.","Cloud shifts service hosting to GitHub rather than customer-operated Server infrastructure.","Merge conflicts arise from changes, not the deployment model.","Cloud repositories can have restricted visibility."],concept:"Enterprise deployment responsibility",hints:["Who maintains the service infrastructure?","Avoid confusing hosting with workflow guarantees."],source:"https://docs.github.com/en/get-started/learning-about-github/githubs-plans"},
  {id:"ghf-059",domain:"Understand Git and GitHub basics",prompt:"A contributor wants to move from the current branch to another existing local branch. Which command expresses that action?",choices:["git fetch","git add","git switch target-branch","git push"],correct:2,explanations:["Fetch retrieves remote information.","Add stages content.","Switch changes the checked-out branch to the named target.","Push transfers commits to a remote."],concept:"Switching branches",hints:["Is the goal to transfer history or change the checkout?","Which action selects another line of work?"],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-060",domain:"Understand Git and GitHub basics",prompt:"An author wants reviewers to distinguish removed lines from added lines in a proposed edit. What should reviewers inspect?",choices:["Only the commit-message list","Only the raw current file","Only the file’s line-attribution view","The change diff"],correct:3,explanations:["Messages describe intent but do not necessarily show line-level edits.","Raw content lacks the before-and-after comparison.","Line attribution identifies prior changes but is not the proposed edit comparison.","A diff presents differences such as additions and deletions."],concept:"Reading diffs",hints:["Which view compares before and after?","Focus on the changed content."],source:"https://docs.github.com/en/pull-requests/reference/branches"},
  {id:"ghf-061",domain:"Understand Git and GitHub basics",prompt:"A Markdown document includes a supported language name after the opening code fence. What benefit does this provide?",choices:["It enables language-aware syntax highlighting","It executes the code on GitHub","It validates the code’s functional correctness","It installs that language in the reader’s environment"],correct:0,explanations:["A supported language identifier helps the renderer highlight code.","Code fences display text rather than execute it.","Highlighting is presentation, not functional validation.","Syntax highlighting does not install runtimes."],concept:"Syntax highlighting",hints:["Is the fence presentation or execution?","What could a renderer do with the language information?"],source:"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-and-highlighting-code-blocks"},
  {id:"ghf-062",domain:"Understand Git and GitHub basics",prompt:"A Markdown checklist shows - [x] Run tests. What does the x signify in the rendered task list?",choices:["The item is still unchecked","The task is marked complete","The text is struck through rather than a task item","The task has a failed automated status check"],correct:1,explanations:["An unchecked task uses a space inside the brackets.","An x inside the checkbox marks the task as completed.","Strikethrough uses different Markdown delimiters.","A checkbox is not an automated test result."],concept:"Completed Markdown tasks",hints:["How does this differ from an empty checkbox?","Separate manual task state from automated checks."],source:"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},
  {id:"ghf-063",domain:"Understand Git and GitHub basics",prompt:"A repository contains program code, design notes, and configuration files. Which can Git version?",choices:["Only the program code","Only files already published on GitHub","All of these file types","Only Markdown documents"],correct:2,explanations:["Git is not restricted to program code.","Local files can be versioned before any publication.","Git can track many types of files in a repository.","Markdown is supported but not exclusive."],concept:"Repository content",hints:["Is Git tied to one document format?","Think about the whole project, not only executable code."],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-064",domain:"Understand Git and GitHub basics",prompt:"Which statement best explains why local commit and push are separate actions?",choices:["Commit only selects files; push records the first local snapshot","Commit downloads remote history; push integrates it locally","Commit always needs the network; push to GitHub never does","Commit records local history; push shares it with a remote"],correct:3,explanations:["Staging selects content; commit records a snapshot before push.","Fetch retrieves history and pull integrates retrieved work.","Local commits can be offline, while pushes to GitHub need connectivity.","Recording and transmitting history are distinct operations."],concept:"Local and remote history",hints:["Where is the change recorded first?","When can collaborators on the remote see it?"],source:"https://docs.github.com/en/get-started/using-git/pushing-commits-to-a-remote-repository"},
  {id:"ghf-065",domain:"Work with GitHub repositories",prompt:"A first-time visitor needs the project’s purpose and basic setup instructions. Which repository file should normally introduce these?",choices:["README.md","CODEOWNERS","LICENSE","A package lockfile"],correct:0,explanations:["A README introduces the project and how to get started.","CODEOWNERS maps paths to responsible reviewers.","LICENSE states legal permissions and conditions.","A lockfile records dependency resolution rather than a project introduction."],concept:"README purpose",hints:["What should a visitor read first?","Separate orientation from legal and dependency metadata."],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes"},
  {id:"ghf-066",domain:"Work with GitHub repositories",prompt:"A maintainer wants to state the legal terms under which others may reuse the repository’s code. Which file is most appropriate?",choices:["CONTRIBUTING.md","LICENSE","CODEOWNERS","A pull request template"],correct:1,explanations:["Contribution guidelines describe how to participate.","A license specifies permissions and conditions for reuse.","CODEOWNERS routes responsibility for paths.","A pull request template structures proposed-change descriptions."],concept:"Repository licensing",hints:["Is this a legal permission or a workflow instruction?","Which document governs reuse?"],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/licensing-a-repository"},
  {id:"ghf-067",domain:"Work with GitHub repositories",prompt:"A contributor needs to know the required test commands and patch submission process. Which file is the best dedicated home for that guidance?",choices:["LICENSE","SECURITY.md","CONTRIBUTING.md","CODEOWNERS"],correct:2,explanations:["A license defines reuse terms.","A security policy explains vulnerability reporting and supported versions.","Contribution guidelines explain the project’s participation workflow.","CODEOWNERS identifies responsible reviewers rather than submission steps."],concept:"Contribution guidelines",hints:["Who is the intended reader?","Distinguish routine participation from vulnerability reporting."],source:"https://docs.github.com/en/communities/setting-up-your-project-for-healthy-contributions/setting-guidelines-for-repository-contributors"},
  {id:"ghf-068",domain:"Work with GitHub repositories",prompt:"A project wants researchers to know where to privately report vulnerabilities. Which dedicated file should contain this policy?",choices:["A pull request template","CODE_OF_CONDUCT.md","CODEOWNERS","SECURITY.md"],correct:3,explanations:["A pull request template structures proposed changes rather than defines the dedicated disclosure policy.","A code of conduct addresses community behavior and conduct reporting.","CODEOWNERS defines review ownership, not disclosure guidance.","SECURITY.md documents security reporting instructions and support information."],concept:"Security policy file",hints:["Is the concern ordinary contribution or sensitive disclosure?","Look for a policy dedicated to vulnerability handling."],source:"https://docs.github.com/en/code-security/how-tos/report-and-fix-vulnerabilities/configure-vulnerability-reporting/add-security-policy"},
  {id:"ghf-069",domain:"Work with GitHub repositories",prompt:"A team wants ready-for-review pull requests touching /payments/ to request review from the payments maintainers. Which mechanism fits?",choices:["A CODEOWNERS path rule","A repository star","A repository description","A release asset"],correct:0,explanations:["CODEOWNERS maps matching paths to users or teams for review requests.","Starring does not assign reviewers.","Descriptions summarize the repository.","Release assets distribute files rather than route reviews."],concept:"Code ownership",hints:["What maps file paths to responsible people?","Separate ownership routing from repository discovery."],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners"},
  {id:"ghf-070",domain:"Work with GitHub repositories",prompt:"Does adding a CODEOWNERS file alone require an owner’s approval before merging?",choices:["Yes, every matching change becomes unmergeable without it","No; an appropriate branch protection or ruleset requirement must also enforce approval","Yes, but only for Markdown files","No, because code owners can never review pull requests"],correct:1,explanations:["Automatic review requests are not by themselves an enforced merge gate.","Ownership and required owner approval are separate configurations.","File type does not create an automatic approval requirement.","Code owners can review; enforcement is the missing element."],concept:"Ownership versus enforcement",hints:["Is requesting review the same as requiring approval?","Which settings control whether merging is blocked?"],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners"},
  {id:"ghf-071",domain:"Work with GitHub repositories",prompt:"A pull request targets main but changes CODEOWNERS on its feature branch. Which version determines the automatic code-owner review requests?",choices:["The newest CODEOWNERS in any fork","The author’s local uncommitted CODEOWNERS","The CODEOWNERS on main, the base branch","Every CODEOWNERS file in the organization combined"],correct:2,explanations:["Other forks do not supply the receiving branch’s ownership rules.","Local uncommitted files do not configure hosted review routing.","Pull requests use code ownership from their base branch.","GitHub does not combine all organization ownership files."],concept:"Code ownership base branch",hints:["Which branch will receive the change?","Should a proposal define its own existing review authority?"],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners"},
  {id:"ghf-072",domain:"Work with GitHub repositories",prompt:"A repository has CODEOWNERS files in .github/, the root, and docs/. Which location takes precedence?",choices:["docs/","The root","All three are merged",".github/"],correct:3,explanations:["Docs is searched after the other supported locations.","The root is searched after .github/.","GitHub uses the first matching location rather than merging files.","GitHub searches .github/ before the root and docs/."],concept:"CODEOWNERS location precedence",hints:["Does GitHub combine all ownership files?","Think about the documented search order."],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners"},
  {id:"ghf-073",domain:"Work with GitHub repositories",prompt:"A company wants new independent services to begin with standard folders and starter files, without inheriting the starter repository’s commit history. What should it use?",choices:["A repository template","A fork of every service","A repository watch subscription","A pull request review"],correct:0,explanations:["A template seeds files into a new project with its own initial history.","A fork preserves a related history and upstream relationship.","Watching configures notifications.","Review evaluates proposed changes rather than generating a new repository."],concept:"Repository templates",hints:["Is the goal a new project or an upstream contribution?","Should the starter’s historical commits carry over?"],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-repository-from-a-template"},
  {id:"ghf-074",domain:"Work with GitHub repositories",prompt:"After a new repository is generated from a template, what happens when the template author edits a starter file?",choices:["The generated repository receives the edit automatically","The generated repository is not automatically synchronized","GitHub automatically opens an update pull request in every generated repository","The edit appears in the generated repository the next time someone clones it"],correct:1,explanations:["Templates do not provide ongoing automatic synchronization.","The new project is independent; later changes must be adopted separately.","Template editing alone does not create update pull requests in generated projects.","Cloning retrieves the generated project’s own history, not later template changes."],concept:"Template independence",hints:["Was a live synchronization relationship created?","Separate initial generation from later maintenance."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-repository-from-a-template"},
  {id:"ghf-075",domain:"Work with GitHub repositories",prompt:"A template includes several branches. A generated repository includes all of them. Why should a maintainer not assume normal GitHub pull requests and merges are available between those generated branches?",choices:["All generated branches are aliases for the same reference","All generated branches are permanently read-only","Their generated histories are unrelated","Every branch keeps a live connection to the template’s original commits"],correct:2,explanations:["Generated branches are distinct rather than aliases.","Template generation does not inherently make branches read-only.","Branches generated from a template have unrelated histories, unlike ordinary branches from shared history.","Generated projects do not retain a live synchronization connection to the template."],concept:"Template branch histories",hints:["Do these branches share ordinary ancestry?","Consult the distinction between generation and forking."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-repository-from-a-template"},
  {id:"ghf-076",domain:"Work with GitHub repositories",prompt:"A maintainer wants to change a file through GitHub’s web interface while keeping review before integration. Which workflow fits?",choices:["Edit the repository description instead","Upload it only as an issue attachment","Change repository visibility","Commit the edit to a new branch and open a pull request"],correct:3,explanations:["A description does not modify the versioned file.","An issue attachment is not a versioned repository edit.","Visibility changes do not edit file content.","A branch and pull request preserve the review workflow for web edits."],concept:"Web file editing",hints:["Where should the versioned change live?","How can review happen before the default branch changes?"],source:"https://docs.github.com/en/repositories/working-with-files/managing-files/editing-files"},
  {id:"ghf-077",domain:"Work with GitHub repositories",prompt:"What should a collaborator expect when a tracked file is deleted in a new commit?",choices:["It disappears from that revision but can remain in earlier history","Every historical copy is automatically erased","The same file is automatically removed from every other branch","Every existing clone immediately deletes its working copy without fetching"],correct:0,explanations:["Git history can retain versions that preceded the deletion.","Ordinary deletion does not purge historical content.","A commit changes its line of history rather than all branches at once.","Other local repositories do not update working files without receiving and applying changes."],concept:"File deletion and history",hints:["Does a new snapshot rewrite all earlier snapshots?","Separate current contents from retained history."],source:"https://docs.github.com/en/repositories/working-with-files/managing-files/deleting-files-in-a-repository"},
  {id:"ghf-078",domain:"Work with GitHub repositories",prompt:"A maintainer adds build/ to .gitignore after build/output.log was already committed. What should they expect?",choices:["The tracked log is erased from all history","The ignore rule alone does not stop tracking the already tracked file","The log is automatically removed from the index","The log is deleted from the local disk automatically"],correct:1,explanations:["Ignore rules do not rewrite history.","Gitignore applies to intentionally untracked files; tracked files need a separate untracking step.","Adding an ignore rule does not untrack existing indexed files.","An ignore pattern is not a file deletion command."],concept:"Ignoring tracked files",hints:["Was the file already in version control?","Separate ignoring new files from removing tracked content."],source:"https://docs.github.com/en/get-started/git-basics/ignoring-files"},
  {id:"ghf-079",domain:"Work with GitHub repositories",prompt:"A user wants to bookmark several repositories without subscribing to all their conversations. Which feature is intended for that?",choices:["Required reviewers","Branch protection","Stars","Organization ownership"],correct:2,explanations:["Required reviewers govern change approval.","Branch protection enforces branch rules.","Stars help users bookmark and discover repositories without being a watch subscription.","Ownership grants responsibilities rather than bookmarks."],concept:"Starring repositories",hints:["Is the goal saving a project or receiving updates?","Separate bookmarking from notification subscriptions."],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/saving-repositories-with-stars"},
  {id:"ghf-080",domain:"Work with GitHub repositories",prompt:"A user wants to organize starred repositories into personal categories. Which feature should they consider?",choices:["Repository milestones","Protected branches","Commit tags","Lists for starred repositories"],correct:3,explanations:["Milestones group issues and pull requests within a repository.","Branch protection governs changes.","Tags identify repository revisions.","Lists organize a user’s starred repositories into collections."],concept:"Star lists",hints:["Whose collection is being organized?","Distinguish personal discovery tools from project work tracking."],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/saving-repositories-with-stars"},
  {id:"ghf-081",domain:"Work with GitHub repositories",prompt:"A project wants people searching for rust and command-line tools to discover it more easily. Which repository metadata should be added?",choices:["Relevant topics","Issue labels only","Code-owner patterns","A milestone for each programming language"],correct:0,explanations:["Topics categorize repositories by purpose or technology for discovery.","Issue labels classify individual work items rather than supply repository topic metadata.","Ownership patterns identify responsible reviewers.","Milestones track delivery work rather than public technology classification."],concept:"Repository topics",hints:["What metadata describes the project’s subject?","Think about discovery rather than enforcement."],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/classifying-your-repository-with-topics"},
  {id:"ghf-082",domain:"Work with GitHub repositories",prompt:"A maintained library reaches a version ready for distribution with release notes and downloadable binaries. Which GitHub feature is designed for this?",choices:["An issue label","A release","A CODEOWNERS rule","A watch filter"],correct:1,explanations:["Labels classify work items, not versioned distributions.","Releases package tagged versions with notes and optional assets.","Ownership rules route review requests.","Watch filters configure notifications."],concept:"Repository releases",hints:["What combines a version with distribution information?","Separate project delivery from task classification."],source:"https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases"},
  {id:"ghf-083",domain:"Work with GitHub repositories",prompt:"A project is no longer maintained, but its code and discussions should remain available as a read-only reference. What should its administrator consider?",choices:["Deleting every file separately","Making every member an owner","Archiving the repository","Creating a new pull request for every visitor"],correct:2,explanations:["Deleting files would remove useful current content without expressing archival status.","Granting ownership increases access rather than preserving a read-only state.","Archiving marks the repository inactive and makes it read-only.","Visitor pull requests do not implement repository-wide archival behavior."],concept:"Archiving repositories",hints:["Should the material remain available?","Which action communicates inactivity without deletion?"],source:"https://docs.github.com/en/repositories/archiving-a-github-repository/archiving-repositories"},
  {id:"ghf-084",domain:"Work with GitHub repositories",prompt:"Which action restores normal write activity to an archived repository?",choices:["Add a star","Download its source ZIP","Follow its owner","Unarchive the repository"],correct:3,explanations:["Starring does not change archival status.","Downloading only copies content.","Following an owner does not alter repository settings.","An authorized administrator can unarchive it to resume updates."],concept:"Restoring archived work",hints:["What setting made the repository read-only?","Distinguish a repository lifecycle setting from a visitor action."],source:"https://docs.github.com/en/repositories/archiving-a-github-repository/archiving-repositories"},
  {id:"ghf-085",domain:"Work with GitHub repositories",prompt:"A maintainer wants to see which packages the project uses and which supported dependencies have known vulnerabilities. Which repository capability is relevant?",choices:["Dependency graph","Profile achievements","Star lists","A pull request title"],correct:0,explanations:["The dependency graph summarizes recognized dependencies and related metadata.","Achievements describe account activity.","Star lists organize bookmarked repositories.","A title cannot inventory the dependency tree."],concept:"Dependency graph",hints:["Where would manifest and lockfile data be summarized?","Distinguish software relationships from social metadata."],source:"https://docs.github.com/en/code-security/concepts/supply-chain-security/dependency-graph"},
  {id:"ghf-086",domain:"Work with GitHub repositories",prompt:"How does GitHub’s dependency graph obtain dependency information?",choices:["Only from repository names","From supported manifests and lockfiles, plus submitted dependency data","Only from README screenshots","From the list of repository watchers"],correct:1,explanations:["A repository name does not describe resolved packages.","Recognized dependency files and the submission API supply graph data.","Screenshots are not dependency manifests.","Watchers are people interested in activity, not package dependencies."],concept:"Dependency graph inputs",hints:["What structured files declare package relationships?","Can externally calculated dependencies also be submitted?"],source:"https://docs.github.com/en/code-security/concepts/supply-chain-security/dependency-graph"},
  {id:"ghf-087",domain:"Work with GitHub repositories",prompt:"A repository Insights view summarizes contributions and activity. What is a responsible interpretation?",choices:["It proves every contributor’s business value","It replaces reviewing the actual work","It provides activity evidence that needs context","It guarantees that active code has no defects"],correct:2,explanations:["Activity measurements do not directly prove business value.","Qualitative review remains necessary.","Insights help investigate activity but require contextual interpretation.","Activity is not a correctness guarantee."],concept:"Interpreting repository insights",hints:["Does counting activity measure all outcomes?","What context might a chart omit?"],source:"https://docs.github.com/en/repositories/viewing-activity-and-data-for-your-repository"},
  {id:"ghf-088",domain:"Work with GitHub repositories",prompt:"A maintainer wants to assess recent pull request and issue activity rather than inspect a single file’s changes. Which repository area is most relevant?",choices:["The personal SSH key settings","The LICENSE file","The local staging area","Repository Insights, including Pulse"],correct:3,explanations:["SSH settings concern authentication.","Licensing concerns reuse terms.","Staging describes local uncommitted content.","Insights and Pulse summarize repository activity across work items."],concept:"Activity overview",hints:["Is the question about one diff or aggregate work?","Look for an overview of repository activity."],source:"https://docs.github.com/en/repositories/viewing-activity-and-data-for-your-repository"},
  {id:"ghf-089",domain:"Work with GitHub repositories",prompt:"A user wants to try an eligible public-preview interface feature for their account. Where should they look?",choices:["Feature preview in the profile menu","The Git commit staging area","The repository LICENSE file","The organization’s billing invoices"],correct:0,explanations:["Feature preview lists eligible preview features and available controls.","Staging has no account feature toggles.","Licensing does not configure GitHub interface previews.","Invoices are not the feature-preview interface."],concept:"Feature preview",hints:["Is this a repository file or an account experience?","Look for opt-in access to experimental features."],source:"https://docs.github.com/en/get-started/using-github/exploring-early-access-releases-with-feature-preview"},
  {id:"ghf-090",domain:"Work with GitHub repositories",prompt:"Why should a team avoid treating a GitHub public-preview feature as having the same commitments as a generally available feature?",choices:["Preview features cannot have documentation","Public preview has different support and service commitments","Preview means the feature is open-source licensed","Preview features cannot accept feedback"],correct:1,explanations:["Public previews can be documented.","The release phase affects support and service-level commitments.","Release phase does not establish source licensing.","Preview programs often explicitly solicit feedback."],concept:"Preview maturity",hints:["What does a release phase communicate?","Distinguish availability for testing from production commitments."],source:"https://docs.github.com/en/get-started/using-github/exploring-early-access-releases-with-feature-preview"},
  {id:"ghf-091",domain:"Work with GitHub repositories",prompt:"A collaborator wants to share a link to a file exactly as it exists today, unaffected by later edits to the branch. What should they use?",choices:["A link only to the repository homepage","A file link using the mutable branch name","A permanent link tied to the file’s commit","A relative file link that follows the currently browsed branch"],correct:2,explanations:["The homepage does not identify the file revision.","A branch can move to newer commits.","A commit-based permalink identifies an immutable revision of the file.","A branch-following relative link does not pin a historical revision."],concept:"File permalinks",hints:["What changes when a branch advances?","How can the URL name a fixed revision?"],source:"https://docs.github.com/en/repositories/working-with-files/using-files/getting-permanent-links-to-files"},
  {id:"ghf-092",domain:"Work with GitHub repositories",prompt:"A contributor needs to understand why a particular file changed last month. Which repository feature should they inspect first?",choices:["Only the current raw file contents","Only the current list of branches","Only the repository’s language summary","The file’s commit history"],correct:3,explanations:["Current contents alone omit the recorded sequence and messages.","Branch names alone do not explain a particular historical edit.","Language composition does not establish change intent.","The file history exposes relevant commits, messages, and changes."],concept:"File history",hints:["What records connect edits to messages and authors?","Focus on versioned evidence for that file."],source:"https://docs.github.com/en/repositories/working-with-files/using-files/viewing-and-understanding-files"},
  {id:"ghf-093",domain:"Work with GitHub repositories",prompt:"Before deleting a repository, what should its owner understand about the action?",choices:["It removes the repository and associated data rather than simply marking it inactive","It is equivalent to closing one issue","It only removes a local clone","It merely unsubscribes the owner from notifications"],correct:0,explanations:["Deletion is materially different from archiving and can remove repository-associated data.","Closing an issue leaves the repository intact.","Hosted deletion is not a local-clone cleanup.","Notification preferences do not determine repository existence."],concept:"Deletion versus archive",hints:["Should users still be able to consult the project?","Distinguish destructive lifecycle changes from personal preferences."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/deleting-a-repository"},
  {id:"ghf-094",domain:"Work with GitHub repositories",prompt:"A new independent repository needs starter files without inherited history, while an existing repository needs an isolated line for ongoing changes. Which pairing fits?",choices:["Use a fork for the starter and a release for ongoing edits","Use a template for the starter and a branch for ongoing changes","Use a branch as the independent repository and a tag as the editable line","Use a source ZIP as a new hosted repository and a release asset as the editable line"],correct:1,explanations:["A fork inherits history, and a release is not an editable line of work.","Templates generate new projects; branches isolate changes within a project.","A branch is not a separate repository, and a tag is a version marker.","Downloading an archive does not create a hosted repository, and assets do not act as branches."],concept:"Templates versus branches",hints:["Are these two tasks creating a project or changing one?","Match each scope to the appropriate versioning mechanism."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-repository-from-a-template"},
  {id:"ghf-095",domain:"Collaborate using GitHub",prompt:"A user reports a reproducible crash that needs ownership and resolution tracking. Which collaboration object is the best starting point?",choices:["A release","A gist","An issue","A repository topic"],correct:2,explanations:["Releases distribute versions rather than track an unresolved defect.","A gist shares content without the repository’s issue workflow.","An issue tracks actionable bugs with discussion and assignment.","Topics classify the repository rather than record a defect."],concept:"Issues for actionable work",hints:["Is there a concrete problem to resolve?","Which object supports tracking its lifecycle?"],source:"https://docs.github.com/en/issues/tracking-your-work-with-issues/learning-about-issues/about-issues"},
  {id:"ghf-096",domain:"Collaborate using GitHub",prompt:"A community wants an open-ended conversation about possible long-term project directions, with no agreed implementation task yet. Which feature fits best?",choices:["A required status check","A release tag","A merge commit","GitHub Discussions"],correct:3,explanations:["Checks evaluate automated results rather than host open-ended planning.","Tags identify historical versions.","Merge commits integrate changes.","Discussions support open-ended community conversations and ideas."],concept:"Discussions versus issues",hints:["Has the group defined actionable work yet?","Where can ideas evolve before a task is committed?"],source:"https://docs.github.com/en/discussions/collaborating-with-your-community-using-discussions/about-discussions"},
  {id:"ghf-097",domain:"Collaborate using GitHub",prompt:"A maintainer opens a draft pull request for an incomplete refactor. What does draft status communicate?",choices:["The proposal is not yet ready for normal review and cannot be merged while a draft","The proposal is invisible to everyone else","The branch contains no commits","The proposal has already passed review"],correct:0,explanations:["Drafts allow early collaboration but must be marked ready before merging.","Draft status is not a privacy control.","Draft pull requests can contain commits and changes.","Draft status does not mean approval."],concept:"Draft pull requests",hints:["Does unfinished mean private?","What transition is needed before merge readiness?"],source:"https://docs.github.com/en/pull-requests/reference/pull-requests"},
  {id:"ghf-098",domain:"Collaborate using GitHub",prompt:"A pull request from fix-export targets main. Which branch is the base branch?",choices:["fix-export","main","Both branches equally","The author’s local backup branch"],correct:1,explanations:["Fix-export is the head branch supplying changes.","The base is the destination branch that would receive the merge.","Head and base have distinct roles.","An unrelated local branch is not the pull request destination."],concept:"Head and base branches",hints:["Which branch receives the proposal?","Separate the source of changes from their target."],source:"https://docs.github.com/en/pull-requests/reference/pull-requests"},
  {id:"ghf-099",domain:"Collaborate using GitHub",prompt:"A reviewer wants to comment on one changed line in a pull request. Which view is intended for this?",choices:["The pull request’s general Conversation tab only","The repository’s raw default-branch file only","Files changed","The repository’s issue search results"],correct:2,explanations:["General conversation supports broader comments rather than selecting a changed line in the diff.","The current raw base file does not provide the proposal’s inline review context.","Files changed exposes the diff and supports inline review comments.","Issue search does not expose the pull request’s inline diff controls."],concept:"Inline review",hints:["Where is the proposed diff displayed?","Does the feedback concern the whole proposal or a specific line?"],source:"https://docs.github.com/en/pull-requests/how-tos/review-pull-requests/reviewing-proposed-changes-in-a-pull-request"},
  {id:"ghf-100",domain:"Collaborate using GitHub",prompt:"A reviewer finds a blocking problem and wants the review outcome to explicitly indicate that changes are needed. Which review action fits?",choices:["Submit an approving review with a note","Submit a comment-only review","Mark the affected file as viewed","Request changes"],correct:3,explanations:["Approval communicates acceptance rather than the requested revision outcome.","A comment-only review supplies feedback without the changes-requested outcome.","Viewed status tracks inspection rather than a review decision.","Request changes records a review outcome indicating issues to address."],concept:"Review outcomes",hints:["Which action formally communicates a revision request?","Separate a review decision from inspection progress."],source:"https://docs.github.com/en/pull-requests/reference/pull-request-reviews"},
  {id:"ghf-101",domain:"Collaborate using GitHub",prompt:"A reviewer proposes a precise replacement for a small code passage. Which feature lets the author apply that suggested text through the review workflow?",choices:["A suggested change in a review comment","A plain-text comment with no suggested-change block","Only marking the file as viewed","Only resolving the discussion thread"],correct:0,explanations:["Suggested changes provide a directly applicable replacement in the review context.","Plain feedback can describe a change but lacks the directly applicable suggestion control.","Viewed status does not encode replacement text.","Resolving a thread records conversational state rather than applies code."],concept:"Suggested changes",hints:["Is the feedback a specific textual replacement?","Which review tool can turn feedback into a commit?"],source:"https://docs.github.com/en/pull-requests/how-tos/review-pull-requests/incorporating-feedback-in-your-pull-request"},
  {id:"ghf-102",domain:"Collaborate using GitHub",prompt:"A pull request targeting the default branch includes Fixes #37 in its description. When is the referenced issue normally closed automatically?",choices:["When the pull request is first opened","When the pull request is merged into the default branch","When someone adds a reaction","When a reviewer reads the description"],correct:1,explanations:["Opening the proposal creates a relationship but does not complete the fix.","The qualifying merge closes the linked issue.","Reactions do not trigger keyword-based closure.","Reading the description does not change issue state."],concept:"Closing keywords",hints:["What event indicates the change has landed?","Pay attention to the destination branch."],source:"https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue"},
  {id:"ghf-103",domain:"Collaborate using GitHub",prompt:"A pull request targets a non-default release branch and its description says Closes #51. What should the author expect from that keyword alone?",choices:["It closes the issue immediately when the description is saved","It creates a closing relationship that completes on any branch merge","It is ignored for automatic issue linking and closure in this case","It closes the issue when the first approving review arrives"],correct:2,explanations:["Saving a description does not complete an issue-closing workflow.","Description closing keywords do not apply to every target branch.","Description closing keywords are interpreted for pull requests targeting the default branch.","An approving review is not the qualifying closure event."],concept:"Default-branch keyword scope",hints:["Does the special keyword apply to every target branch?","Check the prerequisite for automatic linkage."],source:"https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue"},
  {id:"ghf-104",domain:"Collaborate using GitHub",prompt:"A pull request description must close issue 19 in another repository, tools/parser, when merged appropriately. Which syntax expresses that?",choices:["Fixes @tools/parser/19","Fixes #tools/parser/19","Fixes tools/parser:19","Fixes tools/parser#19"],correct:3,explanations:["The at sign denotes mentions rather than this issue-reference form.","The repository name should precede the hash sign.","A colon is not the documented cross-repository issue separator.","The owner/repository#number form qualifies the issue reference."],concept:"Cross-repository issue links",hints:["How is the repository context supplied?","Where does the issue-number delimiter belong?"],source:"https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue"},
  {id:"ghf-105",domain:"Collaborate using GitHub",prompt:"A project receives bug reports missing reproduction steps. What can maintainers add to guide new reporters consistently?",choices:["An issue template or issue form","A release asset","A Git tag","A code-owner pattern"],correct:0,explanations:["Templates and forms guide the information collected in new issues.","Assets distribute versioned downloads.","Tags identify revisions.","Code-owner patterns route review requests rather than structure reports."],concept:"Issue templates",hints:["Where is information collected from the reporter?","Consider a repeatable intake structure."],source:"https://docs.github.com/en/communities/using-templates-to-encourage-useful-issues-and-pull-requests/about-issue-and-pull-request-templates"},
  {id:"ghf-106",domain:"Collaborate using GitHub",prompt:"A team wants every new pull request description to prompt for a summary, testing evidence, and related issues. What should it configure?",choices:["An issue milestone","A pull request template","An organization team slug","A commit tag"],correct:1,explanations:["Milestones group work rather than prefill descriptions.","A pull request template supplies standard prompts to authors.","A team slug identifies a group.","A tag marks a commit rather than a submission format."],concept:"Pull request templates",hints:["Which artifact is created at proposal time?","Distinguish intake guidance from work categorization."],source:"https://docs.github.com/en/communities/using-templates-to-encourage-useful-issues-and-pull-requests/about-issue-and-pull-request-templates"},
  {id:"ghf-107",domain:"Collaborate using GitHub",prompt:"Which search query most directly finds open issues assigned to the current user?",choices:["is:pr is:closed author:@me","is:issue is:open mentions:@me","is:issue is:open assignee:@me","is:issue is:closed assignee:@me"],correct:2,explanations:["This selects closed pull requests authored by the user.","A mention is not the same as assignment.","The qualifiers specify issues, open state, and assignment to the current user.","This selects closed rather than open issues."],concept:"Issue filters",hints:["Is responsibility the same as being mentioned?","Check both object type and lifecycle state."],source:"https://docs.github.com/en/search-github/searching-on-github/searching-issues-and-pull-requests"},
  {id:"ghf-108",domain:"Collaborate using GitHub",prompt:"A maintainer needs open pull requests awaiting their review, not merely authored by them. Which search qualifier identifies that relationship?",choices:["author:@me","assignee:@me","mentions:@me","review-requested:@me"],correct:3,explanations:["Author identifies the creator.","Assignee identifies assigned responsibility, not specifically requested review.","Mentions includes textual references rather than explicit review requests.","Review-requested selects pull requests requesting the user’s review."],concept:"Review-request filters",hints:["What role is the maintainer playing?","Choose an explicit request rather than a general relationship."],source:"https://docs.github.com/en/search-github/searching-on-github/searching-issues-and-pull-requests"},
  {id:"ghf-109",domain:"Collaborate using GitHub",prompt:"A maintainer wants updates only about releases from a repository they can access. What is the most appropriate notification approach?",choices:["Customize the watch subscription to releases","Star the repository and assume all releases will generate notifications","Watch all repository activity without narrowing the types","Subscribe to one existing issue instead"],correct:0,explanations:["Custom watch settings can subscribe to selected activity types such as releases.","Stars are not a release notification subscription.","All-activity watching includes more than the requested release updates.","One issue’s subscription does not subscribe to future repository releases."],concept:"Custom watch subscriptions",hints:["Which feature controls activity delivery?","Can a subscription be narrower than all activity?"],source:"https://docs.github.com/en/subscriptions-and-notifications/concepts/about-notifications"},
  {id:"ghf-110",domain:"Collaborate using GitHub",prompt:"A user wants updates for one issue without following every issue in the repository. What should they do?",choices:["Watch all issue activity across the repository","Subscribe to that issue’s conversation","Star the repository as a substitute for subscribing","Only mark the issue’s existing notification unread"],correct:1,explanations:["Repository-wide issue updates are broader than requested.","A conversation subscription scopes updates to that issue.","Starring is not a subscription to this conversation.","Unread state does not by itself establish the desired ongoing subscription."],concept:"Conversation subscriptions",hints:["How narrow should the update scope be?","Separate personal delivery controls from inbox state."],source:"https://docs.github.com/en/subscriptions-and-notifications/concepts/about-notifications"},
  {id:"ghf-111",domain:"Collaborate using GitHub",prompt:"A user marks a notification as read but does not change their subscription. What should they generally expect?",choices:["All future updates from the thread are permanently muted","The repository is automatically unwatched","Future subscribed activity can still generate notifications","Only a new manual subscription can restore future updates"],correct:2,explanations:["Marking read is not permanently muting future thread updates.","Read state does not change the repository watch setting.","Read state and future subscription delivery are separate concerns.","The existing subscription was not removed by marking an update read."],concept:"Read state versus subscription",hints:["Did the user change delivery settings?","Distinguish processing an update from stopping future updates."],source:"https://docs.github.com/en/subscriptions-and-notifications/concepts/about-notifications"},
  {id:"ghf-112",domain:"Collaborate using GitHub",prompt:"A user no longer needs ongoing updates from a particular thread. Which action changes that conversation subscription?",choices:["Mark only the latest notification as read","Remove the thread from an inbox filter","Hide the thread by changing the issue search query","Unsubscribe from the thread"],correct:3,explanations:["Read state does not cancel an ongoing subscription.","A filter affects the displayed inbox subset rather than thread subscription.","Search presentation does not change future notification delivery.","Unsubscribing stops the existing subscription to ongoing thread activity."],concept:"Unsubscribing",hints:["Is the desired change to presentation or future delivery?","Which control governs the ongoing relationship?"],source:"https://docs.github.com/en/subscriptions-and-notifications/concepts/about-notifications"},
  {id:"ghf-113",domain:"Collaborate using GitHub",prompt:"A developer wants to share a small, versioned example script without creating a full project repository interface. Which feature fits?",choices:["A gist","A milestone","A team","A branch rule"],correct:0,explanations:["Gists are designed for sharing snippets and retain Git history.","Milestones group work items.","Teams group organization members.","Branch rules enforce change requirements."],concept:"Gists",hints:["How much project structure is needed?","Which sharing tool is backed by Git?"],source:"https://docs.github.com/en/get-started/writing-on-github/editing-and-sharing-content-with-gists/creating-gists"},
  {id:"ghf-114",domain:"Collaborate using GitHub",prompt:"A colleague proposes storing a confidential credential in a secret gist because it is not listed publicly. What is the correct response?",choices:["It is safe because only invited accounts can open secret gists","It is unsafe because anyone who obtains the URL can view it","It is safe because secret gists have no URLs","It is safe if the credential is placed in a comment"],correct:1,explanations:["Secret gists are unlisted, not invitation-restricted private storage.","Possession of the URL can expose the content, so credentials must not be stored there.","Secret gists can be shared by URL.","Comments do not establish a safe credential boundary."],concept:"Secret gist privacy",hints:["Does unlisted mean access-controlled?","What happens if the URL is forwarded?"],source:"https://docs.github.com/en/get-started/writing-on-github/editing-and-sharing-content-with-gists/creating-gists"},
  {id:"ghf-115",domain:"Collaborate using GitHub",prompt:"Which statement about gist versioning is correct?",choices:["Gists support comments but never revision history","Only public gists can contain code","Gists are Git repositories that can be cloned and forked","Editing a gist requires converting it into an issue"],correct:2,explanations:["Gists retain Git revision history.","Both public and secret gists can contain code.","Git underlies gists, enabling history, cloning, and forking.","A gist can be edited without becoming an issue."],concept:"Gist history",hints:["Is a gist just a static pasted message?","What follows from using Git underneath?"],source:"https://docs.github.com/en/get-started/writing-on-github/editing-and-sharing-content-with-gists/creating-gists"},
  {id:"ghf-116",domain:"Collaborate using GitHub",prompt:"A repository needs a navigable collection of documentation pages maintained separately from the main code files. Which feature is designed for this?",choices:["A pull request approval","A release asset list","A commit status","A repository wiki"],correct:3,explanations:["An approval is a review outcome rather than documentation structure.","Release assets distribute versioned downloads.","A commit status reports an external check state.","Wikis support multi-page repository documentation."],concept:"Repository wikis",hints:["Is a single introductory file sufficient?","Which feature supports a documentation collection?"],source:"https://docs.github.com/en/communities/documenting-your-project-with-wikis/about-wikis"},
  {id:"ghf-117",domain:"Collaborate using GitHub",prompt:"A team wants to publish a static documentation website from repository files. Which GitHub feature is the best match?",choices:["GitHub Pages","GitHub Issues","GitHub Sponsors","GitHub Mobile"],correct:0,explanations:["Pages publishes static site content from repositories.","Issues track work and conversations.","Sponsors supports financial contributions.","Mobile is a client for collaboration rather than static hosting."],concept:"GitHub Pages",hints:["Does the team need a published website?","Separate content hosting from project discussion."],source:"https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages"},
  {id:"ghf-118",domain:"Collaborate using GitHub",prompt:"A site requires a continuously running server-side Python process to handle requests. Can GitHub Pages provide that runtime?",choices:["Yes; using Python in a site build also provides a persistent request handler","No; Pages provides static hosting rather than an arbitrary server runtime","Yes; uploading Python source automatically starts a web service","Yes; a custom domain changes Pages into server-side hosting"],correct:1,explanations:["Build-time execution does not create a continuously running backend.","Pages can publish generated assets but does not host arbitrary persistent server processes.","Publishing source does not provision a Python request handler.","A custom domain changes addressing rather than the hosting execution model."],concept:"Pages hosting boundary",hints:["Distinguish build-time generation from request-time execution.","What does static hosting mean for a backend?"],source:"https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages"},
  {id:"ghf-119",domain:"Collaborate using GitHub",prompt:"A support discussion has a useful solution that future readers should quickly find. In an answer-enabled category, which action explicitly designates that solution?",choices:["Subscribe to the discussion","Add a thumbs-up reaction only","Mark the helpful response as the answer","Lock the discussion without selecting a response"],correct:2,explanations:["Subscribing controls updates rather than identifies a solution.","A reaction expresses appreciation without setting the answer designation.","Marking an answer highlights the solution in supported categories.","Locking prevents further interaction but does not designate the answer."],concept:"Discussion answers",hints:["What differs between appreciating and formally identifying a solution?","Which action records the resolved question’s outcome?"],source:"https://docs.github.com/en/discussions/collaborating-with-your-community-using-discussions/about-discussions"},
  {id:"ghf-120",domain:"Collaborate using GitHub",prompt:"An issue has evolved into a broad design conversation with no concrete task. What is a suitable way to preserve the conversation in a more appropriate format?",choices:["Delete the issue and its discussion history","Close and lock it without providing a conversation destination","Open a pull request with no proposed changes to serve as the forum","Convert the issue to a discussion where supported"],correct:3,explanations:["Deletion sacrifices the conversation rather than preserves it.","Locking ends participation without moving the conversation to a better format.","Pull requests are intended to review proposed changes.","Issue-to-discussion conversion moves open-ended conversation into the intended tool."],concept:"Moving conversation types",hints:["Has the nature of the work changed?","Which tool better supports exploratory dialogue?"],source:"https://docs.github.com/en/discussions/collaborating-with-your-community-using-discussions/about-discussions"},
  {id:"ghf-121",domain:"Collaborate using GitHub",prompt:"A review thread is marked resolved. What does that indicate by itself?",choices:["That conversation thread is treated as addressed, not that the entire pull request is approved","Every required status check has passed","The pull request is already merged","Every other review thread is resolved"],correct:0,explanations:["Thread resolution is scoped to the conversation; approval is a separate review outcome.","Thread state does not report test execution.","Resolving a thread does not merge changes.","Other threads retain their own states."],concept:"Thread resolution scope",hints:["What is the scope of the action?","Separate conversational progress from merge authorization."],source:"https://docs.github.com/en/pull-requests/how-tos/review-pull-requests/commenting-on-a-pull-request"},
  {id:"ghf-122",domain:"Collaborate using GitHub",prompt:"An author wants to abandon a proposed change without applying its commits to the base branch. What should they do?",choices:["Squash and merge the proposal","Close the pull request without merging","Mark every file viewed","Convert the proposal to draft and leave it open"],correct:1,explanations:["Squashing still integrates the proposed changes.","Closing without merging ends the proposal without applying it to the base.","Viewed status only tracks review progress.","A draft remains an open proposal rather than expressing abandonment."],concept:"Closing versus merging",hints:["Should the destination branch change?","Distinguish ending a proposal from accepting it."],source:"https://docs.github.com/en/pull-requests/how-tos/merge-and-close-pull-requests/closing-a-pull-request"},
  {id:"ghf-123",domain:"Collaborate using GitHub",prompt:"A maintainer requests a teammate’s review on a pull request. How does that differ from assigning the pull request?",choices:["Review requests grant write permission; assignments do not","Assignments count as approvals; review requests are optional comments","Review requests explicitly ask for review; assignment identifies responsibility","Both controls always record the same relationship"],correct:2,explanations:["A review request does not grant repository write permission.","Assignment is not a submitted review outcome.","Review and assignment express different collaboration relationships.","GitHub provides separate controls because the roles differ."],concept:"Reviewer versus assignee",hints:["Does responsibility always mean evaluating the diff?","Which relationship asks for a formal review?"],source:"https://docs.github.com/en/pull-requests/how-tos/create-pull-requests/requesting-a-pull-request-review"},
  {id:"ghf-124",domain:"Collaborate using GitHub",prompt:"A reviewer approves a pull request, but a required automated check is failing. What should the author infer?",choices:["Approval automatically overrides every check","The failure is only a notification preference","The branch is already merged","Review approval and required checks are separate merge conditions"],correct:3,explanations:["An approval does not automatically bypass required checks.","A check result is not merely a subscription setting.","Approval alone does not merge the branch.","A repository can require both satisfactory review and passing checks."],concept:"Review and check conditions",hints:["Can a repository have more than one merge gate?","Separate human judgment from automated results."],source:"https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches"},
  {id:"ghf-125",domain:"Understand Git and GitHub basics",prompt:"An engineer needs a chronological view of commits, including their messages, to investigate when a behavior changed. Which Git command fits?",choices:["git log","git status","git remote -v","git add"],correct:0,explanations:["Log displays recorded commit history.","Status summarizes the current working tree and index.","Remote -v lists remote URLs.","Add stages content rather than displaying recorded history."],concept:"Inspecting commit history",hints:["Is the question about current edits or past snapshots?","Which output would include historical messages?"],source:"https://docs.github.com/en/get-started/using-git/about-git"},
  {id:"ghf-126",domain:"Understand Git and GitHub basics",prompt:"In Git terminology, what does HEAD ordinarily identify during branch-based work?",choices:["The oldest commit in the repository","The currently checked-out position, usually through the current branch","The remote URL used for the next push","All changes currently in the staging area"],correct:1,explanations:["HEAD is not a fixed reference to the oldest commit.","HEAD identifies the checkout’s current position and commonly points to the active branch.","Remote URLs are configured separately from HEAD.","The index contains staged content; HEAD identifies a position in history."],concept:"HEAD",hints:["What identifies where you are working now?","Could this reference move as new commits are made?"],source:"https://docs.github.com/en/get-started/learning-about-github/github-glossary"},
  {id:"ghf-127",domain:"Understand Git and GitHub basics",prompt:"A feature branch has new commits after a tag was created on an earlier commit. What does an unchanged tag still identify?",choices:["Whichever commit is newest on any branch","The newest open pull request","The earlier tagged commit","The current working tree including uncommitted files"],correct:2,explanations:["Tags do not automatically advance to globally newest commits.","Tags refer to Git objects, not pull request lists.","An unchanged tag remains a marker for its original target.","Uncommitted working files are not part of a tag’s target."],concept:"Tags versus moving branches",hints:["Which reference is intended as a version marker?","Does a branch advancing imply every reference advances?"],source:"https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases"},
  {id:"ghf-128",domain:"Work with GitHub repositories",prompt:"A maintainer wants to find the most recent commit that changed each line of a file. Which file view is most useful?",choices:["Raw","Preview","The repository’s branch list","Blame"],correct:3,explanations:["Raw shows file content without line-by-line commit attribution.","Preview renders supported file content rather than shows each line’s change provenance.","Branch names alone do not associate lines with commits.","Blame associates lines with the commits that most recently changed them."],concept:"Line attribution",hints:["Is the goal file content alone or its provenance?","Which view links lines back to historical changes?"],source:"https://docs.github.com/en/repositories/working-with-files/using-files/viewing-and-understanding-files"},
  {id:"ghf-129",domain:"Collaborate using GitHub",prompt:"A team wants a pull request’s many small commits represented by one new commit on the base branch. Which enabled merge method fits?",choices:["Squash and merge","Create a merge commit without squashing","Close without merging","Rebase and merge while preserving separate commits"],correct:0,explanations:["Squashing combines the proposed changes into one commit on the base.","A regular merge retains the branch’s individual commits plus a merge commit.","Closing alone does not integrate changes.","Rebase-and-merge reapplies commits separately rather than consolidating them."],concept:"Squash merging",hints:["Should intermediate commit boundaries remain?","Which method consolidates rather than merely integrates history?"],source:"https://docs.github.com/en/pull-requests/reference/pull-request-merges"},
  {id:"ghf-130",domain:"Apply modern development practices",prompt:"A team wants tests to run whenever a pull request is opened or updated. Which GitHub capability should it configure?",choices:["A repository topic","A GitHub Actions workflow","A static README checklist only","A saved reply"],correct:1,explanations:["Topics categorize projects without running tests.","Actions can automate tests in response to pull request events.","A checklist documents intent but does not execute tests.","Saved replies reuse comment text rather than run automation."],concept:"Continuous integration",hints:["What should respond to repository events?","Distinguish documenting a task from executing it."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-131",domain:"Apply modern development practices",prompt:"Where does a repository normally store GitHub Actions workflow definitions?",choices:["Only in the local .git/hooks folder","In the repository’s LICENSE file","As YAML files under .github/workflows/","As comments on a release"],correct:2,explanations:["Local Git hooks do not define hosted Actions workflows.","LICENSE holds legal terms.","GitHub discovers workflow YAML in .github/workflows/.","Release comments are not workflow definitions."],concept:"Workflow file location",hints:["Must GitHub discover versioned automation configuration?","Separate local hooks from hosted workflows."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-132",domain:"Apply modern development practices",prompt:"In GitHub Actions, what is a runner?",choices:["The person assigned to an issue","A label used to mark urgent bugs","A reusable Markdown checklist","The machine that executes a job"],correct:3,explanations:["Issue assignees are not workflow execution infrastructure.","An urgency label does not execute commands.","A checklist records tasks but is not execution infrastructure.","Runners provide the compute environment for workflow jobs."],concept:"Actions runners",hints:["Where do scripts actually execute?","Separate workflow metadata from computing resources."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-133",domain:"Apply modern development practices",prompt:"A workflow contains a checkout step, a dependency-install step, and a test step in one job. What do these steps normally share?",choices:["The job’s runner environment","Every other job’s working directory automatically","All organization owners’ credentials","The author’s uncommitted laptop files"],correct:0,explanations:["Steps within a job execute in the same runner environment.","Separate jobs do not automatically share working directories.","Owner credentials are not implicitly provided.","Hosted runners do not receive uncommitted laptop state automatically."],concept:"Steps within a job",hints:["Which boundary groups sequential work on one environment?","Do not assume data crosses job boundaries automatically."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-134",domain:"Apply modern development practices",prompt:"A deployment job must wait until a test job succeeds. Which workflow relationship should be configured?",choices:["Use identical job display names","Declare a dependency with needs","List deployment later in the YAML without a dependency","Run both jobs on the same operating-system label only"],correct:1,explanations:["Names do not establish execution dependencies.","Needs expresses the prerequisite relationship between jobs.","YAML listing order alone does not make independent jobs sequential.","Matching runner operating systems does not create a prerequisite relationship."],concept:"Job dependencies",hints:["What expresses a prerequisite rather than a label?","Should the jobs be independent?"],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-135",domain:"Apply modern development practices",prompt:"A library needs the same test job run against several language versions. Which Actions feature avoids manually duplicating the job for each version?",choices:["A repository fork","A pull request template","A matrix strategy","A code-owner rule"],correct:2,explanations:["Forks create separate repositories rather than parameterize jobs.","Templates guide pull request descriptions.","A matrix runs a job with different variable combinations.","Code ownership routes reviews, not runtime combinations."],concept:"Matrix builds",hints:["Which part of the job varies between runs?","Look for parameterized combinations."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-136",domain:"Apply modern development practices",prompt:"An Actions step invokes a shared component with uses to set up a language toolchain. What is that reusable component called?",choices:["A runner","An event","A matrix","An action"],correct:3,explanations:["A runner supplies execution infrastructure rather than the reusable setup component.","An event triggers workflow execution.","A matrix defines combinations of job variables.","An action is a reusable component invoked by workflow steps."],concept:"Reusable actions",hints:["What can a step invoke instead of custom shell code?","Separate the component from its execution machine and trigger."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-137",domain:"Apply modern development practices",prompt:"A repository wants to automate issue labeling rather than build software. Is GitHub Actions an appropriate option?",choices:["Yes; workflows can respond to events beyond code builds","No; Actions only runs compiler commands","No; issue events cannot trigger automation","Only if every issue contains executable code"],correct:0,explanations:["Actions can automate repository tasks such as labeling issues.","Workflows can run many kinds of commands and actions.","Supported issue events can trigger workflows.","Issue content does not have to be executable."],concept:"Automation beyond CI",hints:["Is automation limited to compilation?","What repository events could start a workflow?"],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-138",domain:"Apply modern development practices",prompt:"A job requires specialized hardware on a machine the company operates. Which Actions option should the team evaluate?",choices:["A standard GitHub-hosted runner with no access to that machine","A self-hosted runner","A matrix variable that merely names the hardware","A workflow description of the required machine"],correct:1,explanations:["A standard hosted runner does not become the company-operated hardware.","Self-hosted runners let a company provide and manage its execution machines.","A matrix value alone does not provide hardware or connect a runner.","Documenting a machine does not register it as an execution environment."],concept:"Self-hosted runners",hints:["Who needs to control the execution infrastructure?","Separate selecting resources from merely describing them."],source:"https://docs.github.com/en/actions/get-started/understand-github-actions"},
  {id:"ghf-139",domain:"Apply modern development practices",prompt:"A maintainer needs the error output from a failing Actions test step. Where should they inspect it?",choices:["Only the commit author’s message","Only the workflow’s filename","The relevant workflow run’s job and step logs","Only the successful run from a previous revision"],correct:2,explanations:["A commit message is not the current execution output.","A filename does not reveal the failing command’s output.","Run logs expose the commands and error output for the failed step.","A past successful run does not provide the current failure’s output."],concept:"Workflow diagnostics",hints:["Where is execution output recorded?","Focus on the specific failed run."],source:"https://docs.github.com/en/actions/how-tos/monitor-workflows/use-workflow-run-logs"},
  {id:"ghf-140",domain:"Apply modern development practices",prompt:"While writing a function in a supported editor, a developer wants AI-generated code suggestions. Which tool is designed for this?",choices:["GitHub Pages","GitHub Sponsors","GitHub Projects alone","GitHub Copilot"],correct:3,explanations:["Pages publishes static websites.","Sponsors provides financial support.","Projects tracks work rather than generating editor suggestions.","Copilot offers AI-powered coding assistance in supported environments."],concept:"Copilot suggestions",hints:["Is the task coding assistance or work tracking?","Which tool integrates with the editor’s coding experience?"],source:"https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-in-ides"},
  {id:"ghf-141",domain:"Apply modern development practices",prompt:"Copilot suggests a plausible implementation for an authentication helper. What should the developer do before accepting it into production?",choices:["Review its behavior and validate it with appropriate tests and security checks","Assume generated code has already passed the project’s tests","Skip review because the prompt was detailed","Treat its explanation as a security certification"],correct:0,explanations:["The developer remains responsible for evaluating generated changes.","Suggestions are not evidence that project tests ran successfully.","Prompt detail does not remove review obligations.","An AI explanation does not certify security."],concept:"Responsible AI validation",hints:["Who is accountable for the merged code?","What evidence would validate a suggestion?"],source:"https://docs.github.com/en/copilot/responsible-use/inline-suggestions"},
  {id:"ghf-142",domain:"Apply modern development practices",prompt:"An engineer asks Copilot to explain an unfamiliar function and then asks follow-up questions. Which interaction is the closest match?",choices:["Only accepting an inline code completion","Copilot Chat","Only inspecting a code-review summary without conversation","Only applying a predefined editor snippet"],correct:1,explanations:["An inline completion suggests code but does not by itself provide the described dialogue.","Chat supports conversational questions and follow-up explanations.","A fixed review summary does not supply the requested ongoing explanation dialogue.","A predefined snippet is not contextual conversational assistance."],concept:"Copilot Chat",hints:["Does the workflow involve dialogue?","Distinguish an interactive explanation from inserting code."],source:"https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-in-ides"},
  {id:"ghf-143",domain:"Apply modern development practices",prompt:"A developer wants an IDE-based Copilot workflow that can locate files, edit several of them, run commands, and validate the result while they supervise. Which capability fits?",choices:["A single inline completion only","A saved issue reply","Agent mode","A static README badge"],correct:2,explanations:["An inline completion alone is not a multi-step tool-using workflow.","Saved replies reuse text rather than perform code changes.","Agent mode can combine investigation, edits, and command execution under supervision.","Badges display information but do not implement changes."],concept:"Copilot Agent Mode",hints:["How much of the task is being delegated?","Does it require tools beyond predicting the next code fragment?"],source:"https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-in-ides"},
  {id:"ghf-144",domain:"Apply modern development practices",prompt:"A maintainer delegates a repository change to Copilot’s cloud agent. Where can the agent carry out implementation work?",choices:["Only in the maintainer’s open local terminal","Only in a browser-only editor without compute","Only inside the pull request’s rendered diff view","In an ephemeral cloud development environment with editing and test tools"],correct:3,explanations:["Cloud-agent work does not require using the maintainer’s local terminal as its execution environment.","A browser-only editor does not provide the agent’s cloud execution environment.","The rendered diff shows proposed changes rather than runs implementation tools.","The cloud agent can edit and run tools in a cloud environment for later review."],concept:"Cloud coding agent",hints:["What environment is needed to edit and run tests?","Separate cloud delegation from a lightweight browser editor."],source:"https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-on-github"},
  {id:"ghf-145",domain:"Apply modern development practices",prompt:"An organization wants centrally assigned Copilot access and member policy controls rather than separately managed individual subscriptions. Which plan family is designed for this?",choices:["Copilot Business or Copilot Enterprise","Copilot Free accounts managed separately by each user","Individual Copilot Pro subscriptions without organization licensing","A GitHub repository plan alone with no Copilot licensing"],correct:0,explanations:["Business and Enterprise provide organizational Copilot management.","Separate Free accounts do not provide the requested centralized license administration.","Independent individual subscriptions are not the organizational management model.","A repository plan by itself does not establish organizational Copilot licensing."],concept:"Copilot organizational plans",hints:["Who needs to administer access?","Separate personal usage from centrally governed deployment."],source:"https://docs.github.com/en/copilot/get-started/plans"},
  {id:"ghf-146",domain:"Apply modern development practices",prompt:"How should a learner distinguish Copilot Enterprise from Copilot Business at a stable, high level?",choices:["Business is only a local Git client","Enterprise builds on Business for enterprises using GitHub Enterprise Cloud","Enterprise eliminates the need for human code review","Business cannot have organization policy controls"],correct:1,explanations:["Business is an organizational Copilot plan, not a Git client.","Enterprise includes Business capabilities and targets GitHub Enterprise Cloud customers.","Neither plan removes the need to review generated work.","Business includes centralized management and policy controls."],concept:"Copilot Business versus Enterprise",hints:["Avoid comparing temporary prices or quotas.","Which plan adds enterprise capabilities to an organizational foundation?"],source:"https://docs.github.com/en/copilot/get-started/plans"},
  {id:"ghf-147",domain:"Apply modern development practices",prompt:"A Copilot user can choose among supported chat models. Which statement best describes this capability?",choices:["Every model must be enabled for every account","Model choice guarantees an answer is correct","Available models can differ by plan, client, and organizational policy","Changing the model automatically merges all suggestions"],correct:2,explanations:["Availability is subject to product and policy constraints.","Model selection is not a correctness guarantee.","Plan, usage surface, and organization settings can affect available choices.","Model selection does not authorize merging."],concept:"Multi-model support",hints:["What determines which choices are offered?","Separate flexibility from correctness guarantees."],source:"https://docs.github.com/en/copilot/how-tos/copilot-in-your-ide/chat-with-copilot/change-the-chat-model"},
  {id:"ghf-148",domain:"Apply modern development practices",prompt:"A user changes the model selected for Copilot Chat. What should they infer about the model used for inline suggestions?",choices:["It must change to the same model","Inline suggestions are disabled until the chat ends","The chat setting always overrides any inline-model configuration","The chat selection does not by itself change the inline-suggestion model"],correct:3,explanations:["Chat and inline model configuration are separate.","A chat-model switch does not inherently disable inline suggestions.","The chat selector is not an override for the separate inline configuration.","The documented chat-model switch does not affect the inline-suggestion model."],concept:"Chat versus completion models",hints:["Are chat and inline suggestions the same interaction surface?","Check the scope of the setting being changed."],source:"https://docs.github.com/en/copilot/how-tos/copilot-in-your-ide/chat-with-copilot/change-the-chat-model"},
  {id:"ghf-149",domain:"Apply modern development practices",prompt:"A developer asks Copilot Chat to help write tests for an unfamiliar parser. Which context would most directly help it suggest relevant tests?",choices:["The parser’s expected behavior, edge cases, and the project’s testing conventions","Only the parser filename without its contents or behavior","Only the number of existing test files","Only a request to maximize line count without describing expected outcomes"],correct:0,explanations:["Behavioral expectations and project context help target useful test suggestions.","A filename alone rarely explains the expected behavior.","File counts do not describe what the parser should do.","Test volume alone does not define meaningful correctness checks."],concept:"Context for AI assistance",hints:["What information defines whether a parser result is right?","Distinguish useful behavioral context from volume metrics."],source:"https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-in-ides"},
  {id:"ghf-150",domain:"Apply modern development practices",prompt:"A new contributor needs a cloud-hosted development environment that can build and run the project. Which GitHub feature fits?",choices:["A GitHub Pages site","GitHub Codespaces","A secret gist","A repository star list"],correct:1,explanations:["Pages serves static site content, not a general development environment.","Codespaces provides cloud development environments with runtime compute.","A gist shares snippets.","Star lists organize bookmarks."],concept:"Codespaces purpose",hints:["Does the task require compute as well as editing?","Which option is a development environment?"],source:"https://docs.github.com/en/codespaces/about-codespaces/what-are-codespaces"},
  {id:"ghf-151",domain:"Apply modern development practices",prompt:"A team wants new codespaces to include the same runtimes, extensions, and setup. What should it version in the repository?",choices:["Only manual setup instructions with no environment configuration","Only one contributor’s personal editor preferences","A dev container configuration","Only a GitHub Actions file that runs tests on hosted runners"],correct:2,explanations:["Instructions can help humans but do not automatically configure new codespaces.","Personal preferences do not define the team’s common environment.","Dev container configuration defines a repeatable project environment.","An Actions test workflow does not define a codespace’s development environment."],concept:"Repeatable dev environments",hints:["Can the setup be expressed as code?","What should a new environment read when it starts?"],source:"https://docs.github.com/en/codespaces/setting-up-your-project-for-codespaces/adding-a-dev-container-configuration/introduction-to-dev-containers"},
  {id:"ghf-152",domain:"Apply modern development practices",prompt:"Which file commonly serves as the primary configuration for a repository’s development container?",choices:["package.json","Dockerfile",".github/workflows/build.yml",".devcontainer/devcontainer.json"],correct:3,explanations:["Package.json describes a package and scripts rather than the overall dev container setup.","A Dockerfile may define the image but is referenced by the primary dev container configuration.","Workflow YAML defines Actions automation rather than a development container.","Devcontainer.json defines development-container settings at this common location."],concept:"Dev container configuration file",hints:["Which configuration can refer to an image and editor settings together?","Distinguish the environment definition from one of its components."],source:"https://docs.github.com/en/codespaces/setting-up-your-project-for-codespaces/adding-a-dev-container-configuration/introduction-to-dev-containers"},
  {id:"ghf-153",domain:"Apply modern development practices",prompt:"A repository has no custom dev container configuration. What happens when a supported codespace is created from it?",choices:["Codespaces uses a default development container configuration","Creation always fails solely because devcontainer.json is absent","The codespace copies the creator’s entire local operating system","It falls back to github.dev with no compute environment"],correct:0,explanations:["A default image and configuration support getting started without a custom setup.","A custom configuration is not mandatory for creation.","Codespaces does not clone a user’s local operating system.","The default still provides a compute-backed codespace rather than the browser-only editor."],concept:"Default Codespaces environment",hints:["Is custom configuration mandatory?","Consider a baseline environment for first-time users."],source:"https://docs.github.com/en/codespaces/setting-up-your-project-for-codespaces/adding-a-dev-container-configuration/introduction-to-dev-containers"},
  {id:"ghf-154",domain:"Apply modern development practices",prompt:"A developer changes the image and setup configuration in devcontainer.json. What action applies this to the existing codespace’s development container?",choices:["Only refresh the browser tab","Rebuild the development container","Only commit the file without recreating the container","Only reconnect to the unchanged running container"],correct:1,explanations:["Refreshing the client does not recreate the environment from its new configuration.","Rebuilding applies relevant dev container configuration changes.","Committing records configuration but does not itself rebuild the existing container.","Reconnecting alone does not apply a new container image and setup."],concept:"Applying container configuration",hints:["Does editing configuration necessarily recreate a running environment?","Which lifecycle action applies the new setup?"],source:"https://docs.github.com/en/codespaces/setting-up-your-project-for-codespaces/adding-a-dev-container-configuration/introduction-to-dev-containers"},
  {id:"ghf-155",domain:"Apply modern development practices",prompt:"A maintainer wants a browser editor for a quick text edit and commit without provisioning a development machine. Which option fits?",choices:["A new Codespaces virtual machine","A self-hosted Actions runner","The github.dev web editor","A fresh local clone opened in a desktop editor"],correct:2,explanations:["A codespace provisions compute beyond the stated editing-only requirement.","A runner executes automation rather than supplies this browser editor.","Github.dev provides lightweight browser editing and source control.","A local clone is not the requested browser-only editing workflow."],concept:"github.dev use case",hints:["Is remote compute needed?","Choose the tool whose scope matches editing alone."],source:"https://docs.github.com/en/codespaces/the-githubdev-web-based-editor"},
  {id:"ghf-156",domain:"Apply modern development practices",prompt:"A learner opens github.dev and then needs an interactive terminal to build the project. Which next step best matches that need?",choices:["Stay in the browser-only editor and wait for a runner to appear automatically","Open a second github.dev tab to supply compute","Only change the editor’s syntax-highlighting language","Move to a compute-backed environment such as Codespaces"],correct:3,explanations:["The browser-only editor does not automatically provision a development runner.","A second browser editor tab does not create a compute environment.","Language highlighting changes presentation rather than provides a runtime.","Codespaces supplies a development runtime unlike the browser-only editor."],concept:"github.dev versus Codespaces",hints:["Where would the build process execute?","Distinguish an editor from a full development machine."],source:"https://docs.github.com/en/codespaces/the-githubdev-web-based-editor"},
  {id:"ghf-157",domain:"Apply modern development practices",prompt:"A user opens github.dev, makes edits, and has not committed them. What is an important persistence consideration?",choices:["Uncommitted work is kept in browser storage, so committing regularly is important","Every keystroke is already a pushed Git commit","The edits already exist in a hidden remote branch","Signing out necessarily commits all pending edits"],correct:0,explanations:["The browser editor stores work locally until commits preserve it in repository history.","Editing is not equivalent to recording and publishing a commit.","Uncommitted browser work should not be assumed to exist in remote branch history.","Signing out is not a commit operation."],concept:"Browser editor persistence",hints:["Has a repository commit been created?","What could happen if browser-local data is lost?"],source:"https://docs.github.com/en/codespaces/the-githubdev-web-based-editor"},
  {id:"ghf-158",domain:"Apply modern development practices",prompt:"A codespace runs a web application that the developer wants to preview in a browser. Which development feature is relevant?",choices:["Only pushing its source branch to GitHub","Port forwarding","Only opening the application’s source file in the editor","Only downloading the source repository as a ZIP"],correct:1,explanations:["Publishing source does not expose the running codespace service.","Forwarding a port makes a service running in the codespace reachable for preview.","Viewing source does not connect the browser to the running process.","A source archive is not a network endpoint for the codespace."],concept:"Codespaces port forwarding",hints:["How can the browser reach the running process?","Separate source publishing from a development service endpoint."],source:"https://docs.github.com/en/codespaces/developing-in-a-codespace/forwarding-ports-in-your-codespace"},
  {id:"ghf-159",domain:"Apply modern development practices",prompt:"A developer wants personal shell preferences across codespaces without making them mandatory project settings for all contributors. What should they consider?",choices:["Add every personal alias to the shared project setup","Use only editor color settings to configure shell aliases","A personal dotfiles repository","Configure the project’s Actions runner instead of their codespaces"],correct:2,explanations:["Shared project setup would impose personal preferences on other contributors.","Editor color settings do not configure shell aliases.","Codespaces can use personal dotfiles for shell and tool preferences.","An Actions runner is a different environment from the developer’s codespace."],concept:"Codespaces personalization",hints:["Is the preference personal or project-wide?","How can shell setup travel with the user?"],source:"https://docs.github.com/en/codespaces/about-codespaces/what-are-codespaces"},
  {id:"ghf-160",domain:"Manage projects with GitHub",prompt:"An organization wants one planning space for issues and pull requests from several repositories. Which feature fits?",choices:["One repository’s milestone by itself","A single repository’s label list by itself","One pull request’s review summary","An organization-level GitHub Project"],correct:3,explanations:["A repository milestone does not aggregate other repositories’ work items.","A repository’s label definitions do not supply a cross-repository planning space.","A review summary concerns one proposed change.","Projects can organize work across repositories at the organization level."],concept:"Cross-repository planning",hints:["Is the scope larger than one repository?","Which feature collects work without copying its code?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-161",domain:"Manage projects with GitHub",prompt:"A planner wants to scan many project items and edit their field values in rows and columns. Which Project layout is the closest match?",choices:["Table","Board","Roadmap","An individual file diff"],correct:0,explanations:["Table layout presents dense rows and columns of work-item data.","Boards emphasize cards grouped into columns.","Roadmaps emphasize dates on a timeline.","A diff compares file changes rather than project metadata."],concept:"Project table layout",hints:["What arrangement resembles structured records?","Is the primary need field editing or a timeline?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-162",domain:"Manage projects with GitHub",prompt:"A team wants to move cards through Todo, In progress, and Done columns. Which Project layout best supports that visual workflow?",choices:["Roadmap","Board","Table only","A release asset page"],correct:1,explanations:["Roadmaps display items along a timeline.","A board presents items as cards grouped by a field such as Status.","Tables are useful for rows and fields but are not the requested card layout.","Release assets distribute files rather than track card movement."],concept:"Project board layout",hints:["How should status groups be represented?","Which layout emphasizes cards rather than dates?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-163",domain:"Manage projects with GitHub",prompt:"A product lead wants to visualize planned start and target dates across a timeline. Which Project layout should they choose?",choices:["Board","Table","Roadmap","A status-count chart instead of an item timeline"],correct:2,explanations:["Boards emphasize categories rather than time spans.","Tables list fields but do not provide the timeline layout.","Roadmaps arrange work on a timeline using date information.","A status-count chart aggregates items rather than displays their scheduled intervals."],concept:"Project roadmap layout",hints:["Is the central dimension category or time?","Which view makes overlapping schedules visible?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-164",domain:"Manage projects with GitHub",prompt:"A project needs a Priority field restricted to Low, Medium, or High. Which custom field type best fits?",choices:["Free-form text","A date field","A number field","Single select"],correct:3,explanations:["Text allows arbitrary values rather than enforcing the intended options.","A date represents calendar values.","Numbers do not directly represent the named categories.","Single-select fields provide a defined set of choices."],concept:"Single-select fields",hints:["Must users choose from a controlled vocabulary?","Choose a field type based on the kind of value."],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-165",domain:"Manage projects with GitHub",prompt:"A team plans work in repeating time boxes and wants a Project field that represents those cycles, including breaks. Which type is intended for this?",choices:["Iteration","Text","Assignee","Label"],correct:0,explanations:["Iteration fields represent repeating planning periods and can include breaks.","Text does not inherently model recurring cycles.","Assignees identify people.","Labels categorize work rather than define planning periods."],concept:"Iteration planning",hints:["Does the value represent a recurring period?","Distinguish a scheduling construct from a category."],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-166",domain:"Manage projects with GitHub",prompt:"A project’s triage view should show only urgent items, while its full backlog remains intact. What should the team configure?",choices:["Delete all nonurgent issues","A filtered view","Remove all nonurgent items from the Project","Sort by urgency but display every item"],correct:1,explanations:["Deleting work destroys the backlog rather than preserves it.","Filtering a view changes which items are displayed without deleting the backlog.","Removing items changes the Project’s underlying backlog.","Sorting changes order rather than limits the view to urgent work."],concept:"Filtered project views",hints:["Should hidden work be deleted?","How can presentation change without changing the underlying set?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-167",domain:"Manage projects with GitHub",prompt:"Two stakeholders want different saved arrangements of the same Project items. What should they use?",choices:["Independent copied issues for every stakeholder","One overwritten view with no saved alternatives","Multiple saved project views","Separate credentials for one shared user account"],correct:2,explanations:["Copies create unnecessary duplication of work tracking.","A single overwritten view does not preserve both perspectives.","Saved views retain different filters, layouts, and arrangements of the same items.","Shared-account credentials are not a view-management mechanism."],concept:"Saved views",hints:["Must the work items themselves be duplicated?","Separate data from the ways people inspect it."],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-168",domain:"Manage projects with GitHub",prompt:"An issue already added to a Project is assigned to a new teammate through the Project interface. What happens to the linked issue’s assignee?",choices:["It always remains unchanged because Projects are detached copies","A duplicate issue is automatically created for the new assignee","It changes only after a pull request merges","The assignment is reflected on the issue too"],correct:3,explanations:["Linked issue metadata is synchronized rather than a disconnected copy.","Editing the field does not require duplication.","Assignment synchronization is not dependent on a code merge.","Projects synchronize shared issue metadata in both directions."],concept:"Project and issue synchronization",hints:["Is the Project item a detached copy?","Which fields belong to the linked issue itself?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-169",domain:"Manage projects with GitHub",prompt:"A planning idea belongs in a Project but is not ready to become a repository issue. What can the team add initially?",choices:["A draft issue in the Project","A repository issue that must immediately be assigned to a repository","A draft pull request with no proposed changes","A milestone used as if it were an individual Project work item"],correct:0,explanations:["Draft issues let a Project hold preliminary work before conversion to repository issues.","A repository issue requires the repository decision the team is postponing.","A draft pull request proposes code changes rather than represents an unscoped planning idea.","Milestones group repository issues and pull requests rather than serve this draft-item role."],concept:"Project draft issues",hints:["Can planning precede choosing a repository?","Which item type is designed for preliminary work?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/managing-items-in-your-project/adding-items-to-your-project"},
  {id:"ghf-170",domain:"Manage projects with GitHub",prompt:"A team wants an item’s Project Status to become Done when its linked issue closes. What is the simplest relevant built-in capability?",choices:["A saved view that only sorts by Status","A Project automation workflow","A manually written Done label with no automation","A saved reply asking someone to update Status"],correct:1,explanations:["Sorting changes presentation rather than reacts to lifecycle events.","Built-in workflows can update status in response to issue lifecycle events.","A label alone does not update a separate Project Status field.","A reply can request work but does not automate the field update."],concept:"Built-in project workflows",hints:["What event should update which field?","Look for automation scoped to planning items."],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/automating-your-project/using-the-built-in-automations"},
  {id:"ghf-171",domain:"Manage projects with GitHub",prompt:"A maintainer wants new issues matching a repository filter to enter a Project automatically. Which Project capability should they configure?",choices:["Only a saved filter over items already in the Project","Only a workflow that marks existing items Done when closed","An auto-add workflow","Only an auto-archive workflow"],correct:2,explanations:["A view filter does not add matching issues that are absent from the Project.","A completion workflow handles existing item status rather than intake.","Auto-add workflows add matching repository items to a Project.","Auto-archiving removes items from active planning rather than adds new ones."],concept:"Automatic project intake",hints:["Must intake respond to future matching work?","Distinguish a displayed filter from an automation that adds items."],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/automating-your-project/using-the-built-in-automations"},
  {id:"ghf-172",domain:"Manage projects with GitHub",prompt:"An issue should carry both bug and accessibility categories. Which mechanism is designed for applying these reusable classifications?",choices:["A milestone for each category on that issue","Repository topics applied to the issue","An assignee for each category","Labels"],correct:3,explanations:["Milestones group delivery work and an issue does not use multiple milestones as category tags.","Topics classify repositories rather than individual issues.","Assignees identify responsible people rather than categories.","Labels categorize issues and pull requests and can be combined."],concept:"Labels",hints:["Are these categories or ownership identities?","Can the same item belong to several classifications?"],source:"https://docs.github.com/en/issues/using-labels-and-milestones-to-track-work/managing-labels"},
  {id:"ghf-173",domain:"Manage projects with GitHub",prompt:"A repository wants to group issues and pull requests for a planned release and track their collective progress toward a due date. Which feature fits?",choices:["A milestone","A repository topic","A watch subscription","An individual review comment"],correct:0,explanations:["Milestones group work items and support progress and due-date tracking.","Topics classify the repository as a whole.","Watching controls updates delivered to a user.","A review comment does not group release work."],concept:"Milestones",hints:["Is the group tied to a delivery goal?","Which feature summarizes progress across related work?"],source:"https://docs.github.com/en/issues/using-labels-and-milestones-to-track-work/about-milestones"},
  {id:"ghf-174",domain:"Manage projects with GitHub",prompt:"A support maintainer repeatedly posts the same troubleshooting request and wants reusable comment text they can insert and adapt. Which feature is intended for this?",choices:["A branch rule","Saved replies","A commit tag","A project date field"],correct:1,explanations:["Branch rules govern repository changes.","Saved replies store reusable comment responses.","Tags identify revisions.","Date fields store planning dates, not response templates."],concept:"Saved replies",hints:["What repeated work is being reduced?","Separate reusable conversation text from repository automation."],source:"https://docs.github.com/en/get-started/writing-on-github/working-with-saved-replies/about-saved-replies"},
  {id:"ghf-175",domain:"Manage projects with GitHub",prompt:"A team wants to make it clear who is responsible for following up on a specific issue. Which field should it use?",choices:["Labels only","Milestone","Assignees","Project iteration"],correct:2,explanations:["Labels classify work but do not supply the designated person-responsibility field.","A milestone identifies a delivery grouping.","Assignees communicate who is responsible for work on the issue.","An iteration identifies a planning period rather than a responsible person."],concept:"Issue responsibility",hints:["Which metadata identifies people responsible for follow-up?","Do not confuse responsibility with category or schedule."],source:"https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/assigning-issues-and-pull-requests-to-other-github-users"},
  {id:"ghf-176",domain:"Manage projects with GitHub",prompt:"A manager wants charts showing how Project work is distributed by status, without treating raw activity counts as a complete measure of employee performance. Which feature fits?",choices:["Repository traffic statistics","A single file’s blame view","Only the personal contribution calendar","Project insights"],correct:3,explanations:["Traffic measures repository visits rather than Project status distribution.","Blame attributes file lines to commits.","A contribution calendar does not chart the Project’s item fields.","Project insights visualize item data; interpretation still needs context."],concept:"Project insights",hints:["Where is the relevant planning data already organized?","What does a chart show, and what does it not prove?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/about-projects"},
  {id:"ghf-177",domain:"Manage projects with GitHub",prompt:"A team wants completed items retained as archived Project records rather than active items, without deleting their repository issues. Which action fits?",choices:["Archive the Project items","Delete the items from the Project instead of archiving","Only hide the Status column","Archive the entire repository instead"],correct:0,explanations:["Archiving Project items preserves them as archived records outside active views.","Deletion does not retain the items as Project archive records.","Hiding a column does not change an item’s archive state.","Repository archiving changes the whole repository rather than specific Project items."],concept:"Archiving project items",hints:["Should the planning records remain retrievable?","Which scope needs a lifecycle change?"],source:"https://docs.github.com/en/issues/planning-and-tracking-with-projects/automating-your-project/using-the-built-in-automations"},
  {id:"ghf-178",domain:"Understand privacy, security, and administration",prompt:"Why does adding two-factor authentication strengthen an account protected by a password?",choices:["It makes the account’s repositories public","It requires an additional authentication factor beyond the password","It prevents every possible phishing attack","It replaces all repository permissions"],correct:1,explanations:["Authentication does not determine repository visibility.","An additional factor reduces reliance on possession of the password alone.","Some second-factor methods can still be phished.","Authorization remains separate from authentication."],concept:"Two-factor authentication",hints:["What if someone learns the password?","Distinguish proving identity from granting access."],source:"https://docs.github.com/en/authentication/securing-your-account-with-two-factor-authentication-2fa/about-two-factor-authentication"},
  {id:"ghf-179",domain:"Understand privacy, security, and administration",prompt:"A user with 2FA signs in to GitHub using a registered passkey. Which statement is correct?",choices:["They must publish the private key in their profile","They must disable 2FA first","The passkey can satisfy both the password and 2FA requirements","Passkeys are only labels for saved passwords"],correct:2,explanations:["Private keys must remain protected by the authenticator.","Passkeys can be used while 2FA remains enabled.","GitHub passkeys can complete the sign-in requirements in one step.","Passkeys use public-key cryptography rather than simply rename passwords."],concept:"Passkey sign-in",hints:["How does GitHub treat a passkey for a 2FA user?","Separate a cryptographic credential from a stored password."],source:"https://docs.github.com/en/authentication/authenticating-with-a-passkey/about-passkeys"},
  {id:"ghf-180",domain:"Understand privacy, security, and administration",prompt:"What makes passkeys resistant to common credential-phishing pages?",choices:["The user must paste the private key into every login form","The same reusable code works on all domains","They remove the need to verify which service is being accessed","They are bound to the legitimate website’s domain"],correct:3,explanations:["A passkey does not require exposing the private key in a form.","Passkeys are not universal reusable codes.","Domain binding is precisely a service-identity safeguard.","Authenticators bind the credential to the website domain, resisting lookalike sites."],concept:"Passkey phishing resistance",hints:["Could a lookalike site use the same credential ceremony?","Think about the relationship between credential and service identity."],source:"https://docs.github.com/en/authentication/authenticating-with-a-passkey/about-passkeys"},
  {id:"ghf-181",domain:"Understand privacy, security, and administration",prompt:"A developer enables 2FA and wants to reduce the risk of being locked out after losing a phone. What should they do?",choices:["Store recovery codes securely and configure appropriate fallback methods","Post recovery codes in a repository issue","Rely only on remembering the repository URL","Share their password with every teammate"],correct:0,explanations:["Protected recovery material and alternate methods support account recovery.","Posting codes exposes authentication recovery capability.","A URL does not establish account control.","Sharing a password weakens security and does not replace proper recovery setup."],concept:"Account recovery preparation",hints:["What trusted method remains if the primary device is lost?","Keep recovery material separate from public collaboration."],source:"https://docs.github.com/en/authentication/securing-your-account-with-two-factor-authentication-2fa/configuring-two-factor-authentication-recovery-methods"},
  {id:"ghf-182",domain:"Understand privacy, security, and administration",prompt:"A team needs a repository that anyone on the internet can read without being invited. Which visibility fits?",choices:["Private","Public","Internal only","Secret gist visibility"],correct:1,explanations:["Private repositories require appropriate access.","Public repositories are readable by everyone on the internet.","Internal visibility is scoped to an enterprise rather than the whole internet.","Secret gist is not a repository visibility option and is unlisted rather than invitation-private."],concept:"Public visibility",hints:["Who is the intended reading audience?","Distinguish enterprise-wide access from internet-wide access."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/about-repositories"},
  {id:"ghf-183",domain:"Understand privacy, security, and administration",prompt:"A team wants confidential project files readable only by authorized people, not the entire enterprise or internet. Which repository visibility is the best starting point?",choices:["Public","Internal","Private","Starred"],correct:2,explanations:["Public allows internet-wide reading.","Internal permits broader enterprise-member reading.","Private restricts access to authorized users subject to administrative access.","Starring is a bookmark state, not a visibility boundary."],concept:"Private visibility",hints:["How broad should the reading audience be?","Choose an access boundary rather than a personal bookmark."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/about-repositories"},
  {id:"ghf-184",domain:"Understand privacy, security, and administration",prompt:"An enterprise enables internal repositories. What is their intended visibility scope?",choices:["Every anonymous internet visitor","Only the person who created each repository","Only members of one local Git clone","Enterprise members rather than the general public"],correct:3,explanations:["Internal is not internet-public visibility.","Internal repositories are broader than creator-only access.","Local clones do not define hosted visibility.","Internal visibility enables enterprise-wide reading within the documented enterprise boundary."],concept:"Internal visibility",hints:["What organizational boundary does internal describe?","Separate enterprise membership from anonymous access."],source:"https://docs.github.com/en/enterprise-cloud@latest/repositories/creating-and-managing-repositories/about-repositories"},
  {id:"ghf-185",domain:"Understand privacy, security, and administration",prompt:"Does permission to read a public repository automatically permit pushing commits directly to it?",choices:["No; write access is a separate permission","Yes; public means unrestricted modification","Yes, after starring it","Yes, after downloading a ZIP"],correct:0,explanations:["Visibility grants reading; direct modification depends on authorization.","Public reading does not grant direct write rights.","Starring does not elevate permissions.","Downloading does not change authorization."],concept:"Visibility versus write access",hints:["Are reading and modifying the same capability?","Consider why outside contributors use pull requests."],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/about-repositories"},
  {id:"ghf-186",domain:"Understand privacy, security, and administration",prompt:"A non-code contributor needs to read and discuss an organization repository, with no responsibility to manage issues or push code. Which standard repository role is the least-privileged fit?",choices:["Admin","Read","Write","Maintain"],correct:1,explanations:["Admin grants far more authority than needed.","Read supports viewing and discussing without code-write authority.","Write includes code-pushing capabilities beyond the requirement.","Maintain is intended for broader repository management."],concept:"Repository Read role",hints:["What is the minimum required capability?","Avoid granting administration for participation alone."],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/repository-roles-for-an-organization"},
  {id:"ghf-187",domain:"Understand privacy, security, and administration",prompt:"A support contributor must proactively label and manage issues but should not push code. Which standard organization-repository role is the closest fit?",choices:["Read","Write","Triage","Admin"],correct:2,explanations:["Read does not supply the intended proactive management role.","Write adds code-pushing access beyond the need.","Triage is intended for managing issues and pull requests without write access.","Admin unnecessarily grants sensitive repository control."],concept:"Repository Triage role",hints:["Does the task require modifying code?","Which role sits between basic reading and code writing?"],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/repository-roles-for-an-organization"},
  {id:"ghf-188",domain:"Understand privacy, security, and administration",prompt:"An engineer needs to actively push project code but does not need repository administration. Which standard role is the least-privileged fit?",choices:["Read","Triage","Admin","Write"],correct:3,explanations:["Read does not grant code pushing.","Triage supports work-item management without code-write access.","Admin grants unnecessary destructive and sensitive capabilities.","Write is intended for active code contributors."],concept:"Repository Write role",hints:["Which permission is essential to the job?","Choose the smallest standard role that includes code updates."],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/repository-roles-for-an-organization"},
  {id:"ghf-189",domain:"Understand privacy, security, and administration",prompt:"A project manager needs broad day-to-day repository management but should not have sensitive or destructive administrator powers. Which standard role is designed for this?",choices:["Maintain","Read","Triage","Admin"],correct:0,explanations:["Maintain targets repository management without the full sensitive and destructive admin authority.","Read is insufficient for broad repository management.","Triage primarily supports issues and pull requests without code write access.","Admin includes powers the requirement explicitly avoids."],concept:"Repository Maintain role",hints:["Is the need broader than issue triage?","Which role deliberately stops short of full administration?"],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/repository-roles-for-an-organization"},
  {id:"ghf-190",domain:"Understand privacy, security, and administration",prompt:"Under the standard organization-repository roles, which role includes full repository control, including destructive actions such as repository deletion?",choices:["Write","Admin","Triage","Read"],correct:1,explanations:["Write supports contribution rather than full repository administration.","Admin provides full repository access, including sensitive and destructive actions.","Triage does not provide repository deletion authority.","Read is limited to viewing and participation."],concept:"Repository Admin role",hints:["Which role is at the highest standard privilege level?","Distinguish contributor capabilities from destructive administration."],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/repository-roles-for-an-organization"},
  {id:"ghf-191",domain:"Understand privacy, security, and administration",prompt:"A company wants repository access managed for a whole engineering group rather than individually for each member. Which organization feature fits?",choices:["Repository topics","Issue milestones","Teams","Release tags"],correct:2,explanations:["Topics categorize repositories without granting access.","Milestones group work items.","Teams group organization members and can receive repository permissions.","Tags identify versions rather than people’s access."],concept:"Team-based permissions",hints:["What groups people rather than tasks?","How can membership simplify repeated access changes?"],source:"https://docs.github.com/en/organizations/organizing-members-into-teams/about-teams"},
  {id:"ghf-192",domain:"Understand privacy, security, and administration",prompt:"A parent engineering team is granted write access to a repository. What access relationship applies to its nested child teams?",choices:["Child teams receive only read access regardless of the parent’s grant","Parent permissions never affect child teams","The grant flows to unrelated sibling teams but not children","Child teams inherit the parent’s repository access permissions"],correct:3,explanations:["Inheritance is not automatically reduced to read access.","Nested teams do inherit parent repository access.","The inheritance follows the parent-child relationship, not unrelated siblings.","Nested teams inherit access permissions from their parent teams."],concept:"Nested team inheritance",hints:["Which direction does permission inheritance flow?","Distinguish a hierarchical relationship from unrelated team membership."],source:"https://docs.github.com/en/organizations/organizing-members-into-teams/about-teams"},
  {id:"ghf-193",domain:"Understand privacy, security, and administration",prompt:"A contractor needs access to one organization repository but should not join the organization. Which relationship is designed for this?",choices:["Outside collaborator","Organization owner","Parent team maintainer","Enterprise owner"],correct:0,explanations:["Outside collaborators can receive access to specific repositories without organization membership.","Ownership grants far broader administrative access and membership.","Team membership is for organization members, and maintenance is unnecessary.","Enterprise ownership greatly exceeds the stated scope."],concept:"Outside collaborators",hints:["Does this person need membership or only repository access?","Keep access scoped to the required resource."],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/adding-outside-collaborators-to-repositories-in-your-organization"},
  {id:"ghf-194",domain:"Understand privacy, security, and administration",prompt:"A finance specialist needs to manage organization payment information without full organization ownership. Which predefined role is intended for that responsibility?",choices:["Team maintainer","Billing manager","Repository triage","Code owner"],correct:1,explanations:["Team maintainers administer team settings rather than organization payment information.","Billing managers manage the organization’s billing settings.","Repository triage concerns work-item management.","Code ownership routes reviews for files."],concept:"Billing administration",hints:["Which scope concerns payment rather than code?","Avoid full ownership for a specialized administrative task."],source:"https://docs.github.com/en/organizations/managing-peoples-access-to-your-organization-with-roles/roles-in-an-organization"},
  {id:"ghf-195",domain:"Understand privacy, security, and administration",prompt:"What is a core purpose of Enterprise Managed Users?",choices:["Keeping employee account provisioning entirely independent of the company IdP","Giving an IdP control over every unrelated personal GitHub account","Managing user provisioning and authentication through an external identity provider","Synchronizing repository files to an IdP instead of managing account identities"],correct:2,explanations:["EMUs specifically integrate account lifecycle management with the IdP.","Enterprise-managed identities are distinct from unrestricted control over unrelated personal accounts.","An IdP manages the lifecycle and authentication of enterprise-managed accounts.","EMU integration concerns identity and access, not replacing Git repository storage."],concept:"Enterprise Managed Users",hints:["Who should control the employee identity lifecycle?","Separate identity management from repository storage."],source:"https://docs.github.com/en/enterprise-cloud@latest/admin/concepts/identity-and-access-management/enterprise-managed-users"},
  {id:"ghf-196",domain:"Understand privacy, security, and administration",prompt:"An employee with a managed user account wants to use that same account to contribute to an unrelated public project outside the enterprise. What limitation should they recognize?",choices:["Managed accounts automatically become maintainers of public projects","Managed accounts are ordinary unrestricted personal identities","Public collaboration is enabled by starring the project","Managed user accounts are restricted from collaborating outside their enterprise"],correct:3,explanations:["The account type grants no public-project maintainer authority.","Managed accounts have enterprise-specific restrictions.","Stars cannot change managed-account boundaries.","Enterprise-managed identities cannot be used as unrestricted external collaboration accounts."],concept:"Managed account boundaries",hints:["Is the account intended for enterprise-scoped work?","Check identity restrictions rather than repository popularity."],source:"https://docs.github.com/en/enterprise-cloud@latest/admin/concepts/identity-and-access-management/enterprise-managed-users"},
  {id:"ghf-197",domain:"Understand privacy, security, and administration",prompt:"An enterprise explicitly disables a Copilot feature through policy. Can an organization administrator independently re-enable it for that organization’s governed access?",choices:["No; the organization cannot override that enterprise-enforced setting","Yes; organization settings always take precedence over enterprise policy","Yes; each member’s personal preference overrides the enterprise restriction","Yes; a repository administrator can override it for one repository"],correct:0,explanations:["Enterprise-enforced feature policies constrain organization settings.","Organization choices remain within enterprise-enforced constraints.","Individual preferences do not supersede the enterprise restriction for governed access.","Repository administration does not override an enterprise-enforced Copilot feature policy."],concept:"Copilot policy precedence",hints:["Which administrative scope set the constraint?","Distinguish delegated choices from enforced policy."],source:"https://docs.github.com/en/copilot/how-tos/administer-copilot/manage-for-organization/manage-policies"},
  {id:"ghf-198",domain:"Understand privacy, security, and administration",prompt:"An organization wants to control which Copilot features and models are available to members licensed by that organization. Where should an authorized administrator manage this?",choices:["Only each member’s individual editor preferences","The organization’s Copilot policy settings, subject to enterprise policy","Only the repository’s CODEOWNERS file","Only the branch protection rule for main"],correct:1,explanations:["Personal editor preferences do not establish organization-wide service policy.","Organization Copilot policies control feature and model availability within enterprise constraints.","Code ownership defines review responsibility, not Copilot feature availability.","Branch protection governs repository changes rather than organization Copilot model policy."],concept:"Organization Copilot governance",hints:["Which administrative scope grants those licenses?","Keep service policy separate from repository workflow rules."],source:"https://docs.github.com/en/copilot/how-tos/administer-copilot/manage-for-organization/manage-policies"},
  {id:"ghf-199",domain:"Understand privacy, security, and administration",prompt:"A team wants main to accept changes only after required review and passing checks for contributors who cannot bypass the rules. What should it configure?",choices:["A descriptive branch name only","A README request that contributors be careful","Branch protection or an appropriate ruleset","A repository topic named protected"],correct:2,explanations:["Names do not enforce merge requirements.","Written guidance does not implement technical gates.","Branch protections and rulesets can enforce review and check requirements.","Topics are discoverability metadata rather than enforcement."],concept:"Protected branch requirements",hints:["Is a written convention sufficient?","Which settings can block noncompliant integration?"],source:"https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches"},
  {id:"ghf-200",domain:"Understand privacy, security, and administration",prompt:"An administrator can currently bypass a classic branch protection rule. The team wants that rule applied to administrators too. What should it inspect?",choices:["Only the number of required checks","Only the code-owner file’s path patterns","Only whether the branch name contains main","The rule’s bypass-related enforcement settings"],correct:3,explanations:["Adding checks alone does not remove an administrator’s exemption.","Ownership patterns identify reviewers rather than determine administrator bypass.","A branch name by itself does not establish administrator enforcement.","Classic branch protection can be configured to apply restrictions to administrators rather than allow the default bypass."],concept:"Branch protection bypass",hints:["Who is exempt from the current rule?","Review enforcement scope rather than adding more requirements."],source:"https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches"},
  {id:"ghf-201",domain:"Understand privacy, security, and administration",prompt:"An organization uses classic branch protection rules and several patterns match one branch. Which statement should an administrator know?",choices:["Only one classic branch protection rule applies at a time; rulesets provide a different layering model","Every matching classic rule is always combined","The newest commit chooses a rule at random","Matching multiple patterns disables protection"],correct:0,explanations:["Classic branch protection uses one applicable rule, unlike layered rulesets.","Classic rules do not all combine merely because patterns match.","Rule selection is not random per commit.","Overlapping patterns do not inherently disable protection."],concept:"Branch rules versus rulesets",hints:["Does the question concern classic rules or rulesets?","Avoid assuming their combination models are identical."],source:"https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches"},
  {id:"ghf-202",domain:"Understand privacy, security, and administration",prompt:"A valid access token was accidentally committed to a public repository. What should be the first credential-response step?",choices:["Only delete the file in a new commit","Revoke or rotate the exposed credential","Rename the branch containing it","Add the token file to .gitignore and stop"],correct:1,explanations:["Historical copies and existing exposure remain after ordinary deletion.","Revocation or rotation removes the exposed credential’s usefulness for access.","Renaming does not invalidate the token.","Ignore rules neither invalidate credentials nor erase prior commits."],concept:"Exposed credentials",hints:["Could someone already have copied the value?","What stops that value from authorizing requests?"],source:"https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/removing-sensitive-data-from-a-repository"},
  {id:"ghf-203",domain:"Understand privacy, security, and administration",prompt:"A developer creates a personal access token with broad permissions. Can that token give them organization-owner powers they do not possess?",choices:["Yes; granting an organization-admin scope also promotes its owner","Yes; API credentials are exempt from the user’s repository permissions","No; a token cannot exceed its owner’s access","Yes; omitting an expiration grants administrative authority"],correct:2,explanations:["A scope does not promote the underlying identity to an organization owner.","API credentials do not bypass their owner’s authorization limits.","A token is constrained by the owner’s access as well as its granted permissions.","Expiration affects credential lifetime rather than elevates authority."],concept:"Token authority limits",hints:["Whose authority does the token represent?","Can a credential grant powers absent from the identity behind it?"],source:"https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens"},
  {id:"ghf-204",domain:"Understand privacy, security, and administration",prompt:"A supported automation task needs read access to one repository through a fine-grained personal access token. Which configuration follows least privilege?",choices:["All repositories with every permission","Organization administration even though unused","Write access to unrelated repositories","Only the required repository and read permissions"],correct:3,explanations:["Broad access exceeds the stated need.","Unused administrative authority increases risk.","Unrelated write access is unnecessary.","Restricting repository scope and permissions limits potential exposure."],concept:"Fine-grained token scope",hints:["What is the smallest resource set required?","Should a read-only task receive write authority?"],source:"https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens"},
  {id:"ghf-205",domain:"Understand privacy, security, and administration",prompt:"A company wants a default repository permission level that applies to its organization members before additional grants. Which setting addresses this?",choices:["Organization base permissions","A direct collaborator grant for one person on one repository","A CODEOWNERS entry for every source path","A required-review count on the default branch"],correct:0,explanations:["Base permissions define members’ default repository access within the organization.","A specific collaborator grant does not set the membership-wide baseline.","Ownership entries route reviews rather than grant organization-wide default access.","Review counts control integration requirements rather than general access defaults."],concept:"Organization base permissions",hints:["What is the baseline before specific team or user grants?","Which scope manages membership-wide defaults?"],source:"https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/repository-roles-for-an-organization"},
  {id:"ghf-206",domain:"Understand privacy, security, and administration",prompt:"A team is about to make a confidential repository public. What review most directly addresses the risk of disclosing sensitive information?",choices:["Only check the current README and assume the rest is hidden","Check current files and retained history for sensitive information","Only check whether contributors have enabled notifications","Only confirm that the repository has an open pull request"],correct:1,explanations:["Other files and earlier revisions can also disclose information.","Public visibility can expose both repository content and its history, so sensitive material must be assessed.","Notification settings do not determine what public readers can access.","Pull request existence does not establish disclosure safety."],concept:"Visibility change risk",hints:["What could a new public reader inspect?","Does deleting a value from the latest revision erase its past?"],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/managing-repository-settings/setting-repository-visibility"},
  {id:"ghf-207",domain:"Understand privacy, security, and administration",prompt:"A repository has code owners configured, but a proposed individual owner has only Read access. What must be corrected for that person to function as a code owner?",choices:["They only need to subscribe to every pull request","Read access is sufficient once their username appears in CODEOWNERS","They need the required write permission to the repository","Moving the same ownership rule into docs/ removes the access requirement"],correct:2,explanations:["Subscriptions do not grant code-owner eligibility.","An ownership entry does not grant the required repository permission.","Code owners must have write permission to the repository.","Changing the supported file location does not waive owner access requirements."],concept:"Code-owner access requirement",hints:["Does responsibility routing replace access requirements?","Check the documented minimum permission for owners."],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners"},
  {id:"ghf-208",domain:"Explore the GitHub community",prompt:"An organization uses an open-source library and wants to help sustain its eligible maintainers financially through GitHub. Which feature should it consider?",choices:["A repository topic","A required reviewer","A branch rule","GitHub Sponsors"],correct:3,explanations:["Topics aid discovery rather than transfer financial support.","Review requests ask for feedback on changes.","Branch rules enforce repository workflows.","Sponsors facilitates financial support for eligible open-source people and organizations."],concept:"GitHub Sponsors",hints:["Is the desired contribution money or code?","Which service supports maintainer sustainability?"],source:"https://docs.github.com/en/sponsors/getting-started-with-github-sponsors/about-github-sponsors"},
  {id:"ghf-209",domain:"Explore the GitHub community",prompt:"A designer wants to contribute to an open-source project but does not write code. Which contribution is still valuable?",choices:["Improving usability documentation and reporting clear reproduction steps","Only increasing the repository’s star count counts as contribution","Contributions must consist of compiled source files","Only repository owners can report user problems"],correct:0,explanations:["Documentation, design feedback, and well-described problems can advance open-source work.","Stars express interest, but useful participation extends much further.","Open-source contributions are not limited to compiled code.","Users can report problems through the project’s supported channels."],concept:"Non-code contributions",hints:["What helps users and maintainers besides implementation?","Consider the whole project experience."],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/finding-ways-to-contribute-to-open-source-on-github"},
  {id:"ghf-210",domain:"Explore the GitHub community",prompt:"A newcomer is selecting a first contribution. Which signal is most useful for finding work a project intends to be approachable for beginners?",choices:["The issue has the largest comment count regardless of topic","An issue labeled good first issue, considered alongside its context and guidelines","The oldest unresolved pull request regardless of scope","The repository has the most stars regardless of task difficulty"],correct:1,explanations:["Comment volume can indicate complexity rather than beginner suitability.","Maintainers use good first issue to highlight approachable work, though context still matters.","Age alone does not make work beginner-friendly.","Popularity does not indicate whether an individual task is suitable."],concept:"Finding beginner-friendly work",hints:["What explicit signal might maintainers provide?","Is a label useful without reading the actual task?"],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/finding-ways-to-contribute-to-open-source-on-github"},
  {id:"ghf-211",domain:"Explore the GitHub community",prompt:"Before starting a substantial contribution to an unfamiliar project, what should a contributor do?",choices:["Assume their usual workflow overrides project conventions","Change the project’s license without discussion","Read the project guidelines and discuss scope when appropriate","Demand direct write access before investigating"],correct:2,explanations:["Projects can have different requirements and conventions.","Licensing changes require careful project authorization and are not a starting assumption.","Understanding expectations and coordinating scope improves the chance of a useful contribution.","Outside contributions commonly use forks and pull requests without direct write access."],concept:"Respecting contribution processes",hints:["How can unnecessary rework be avoided?","Whose conventions govern the receiving project?"],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/contributing-to-open-source"},
  {id:"ghf-212",domain:"Explore the GitHub community",prompt:"A contributor lacks write access to a public upstream project but wants to propose a code change. Which workflow is appropriate?",choices:["Edit a local ZIP and assume upstream updates automatically","Star the project to gain push permission","Create a template copy and assume it is already linked for contribution","Fork the project, commit changes on a branch, and open an upstream pull request"],correct:3,explanations:["ZIP edits are not submitted to upstream automatically.","Stars do not grant write access.","A template creates an independent project rather than the normal fork relationship.","Fork-based changes can be proposed to upstream through a pull request."],concept:"Fork-based contributions",hints:["Where can the contributor push their own work?","How is the upstream project asked to review it?"],source:"https://docs.github.com/en/pull-requests/how-tos/work-with-forks/fork-a-repo"},
  {id:"ghf-213",domain:"Explore the GitHub community",prompt:"A fork has fallen behind its upstream project. What should its maintainer do before building on the latest upstream work?",choices:["Synchronize the fork with upstream changes","Create a new local branch from the fork’s unchanged old default branch","Push the unchanged fork branch again without retrieving upstream commits","Download an upstream ZIP and assume the fork’s hosted history changed"],correct:0,explanations:["Syncing incorporates current upstream changes into the fork’s history.","Branching from old history does not retrieve the missing changes.","Publishing the same history does not incorporate upstream work.","An archive download does not update a hosted fork’s history."],concept:"Keeping a fork current",hints:["Which repository is the source of newer work?","What operation brings the two histories back into alignment?"],source:"https://docs.github.com/en/pull-requests/how-tos/work-with-forks/syncing-a-fork"},
  {id:"ghf-214",domain:"Explore the GitHub community",prompt:"A contributor notices outdated setup instructions in a community-maintained template. They want future users generating new projects to get corrected instructions. Where should they propose the shared fix?",choices:["Only in one already-generated project’s README","In a pull request to the template repository itself","Only in an unshared local copy of the template","Only by renaming their generated repository"],correct:1,explanations:["Changing one generated project does not update the source template for future users.","Updating the source template improves the starter files used by future generated projects.","An unshared edit cannot improve the community’s template.","A generated repository’s name does not change template content."],concept:"Contributing to shared templates",hints:["Which repository supplies future starter content?","Does editing a generated project update the source pattern?"],source:"https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-repository-from-a-template"},
  {id:"ghf-215",domain:"Explore the GitHub community",prompt:"A company encourages teams to discover and contribute to each other’s private enterprise projects using pull requests and shared maintainer practices. What is this approach called?",choices:["Public-domain dedication","Repository archiving","InnerSource","Anonymous mirroring"],correct:2,explanations:["Public-domain dedication concerns legal rights rather than internal collaboration practices.","Archiving makes projects inactive.","InnerSource applies open-source-style collaboration within an organization or enterprise.","Mirroring copies content but does not describe this contribution culture."],concept:"InnerSource",hints:["Where are open-source-style practices being applied?","Does collaboration require making the code public?"],source:"https://docs.github.com/en/enterprise-cloud@latest/admin/concepts/enterprise-best-practices/use-innersource"},
  {id:"ghf-216",domain:"Explore the GitHub community",prompt:"A nonsensitive reusable internal service is hard for other enterprise teams to find. Which change most directly supports InnerSource discovery without making it public?",choices:["Keep it inaccessible to other teams and rely only on word of mouth","Publish only the repository name with no access or documentation","Move its documentation to an undisclosed personal repository","Use suitable internal visibility, useful topics, and clear documentation"],correct:3,explanations:["Inaccessible code and informal discovery impede cross-team reuse.","A name alone does not let people inspect and understand the service.","Undisclosed personal documentation makes shared discovery harder.","Appropriate visibility and discoverable documentation help authorized teams find and reuse work."],concept:"Discoverable InnerSource",hints:["Can employees find and understand the project?","Separate wider internal discovery from public release."],source:"https://docs.github.com/en/enterprise-cloud@latest/admin/concepts/enterprise-best-practices/use-innersource"},
  {id:"ghf-217",domain:"Explore the GitHub community",prompt:"A developer wants public activity from a particular maintainer to appear in their GitHub activity experience. Which action is relevant?",choices:["Follow the maintainer’s user account","Watch one issue as a substitute for following the person","Clone one repository as a substitute for following the person","Pin their own repository and assume it subscribes to the maintainer"],correct:0,explanations:["Following people helps users stay informed about their public activity.","An issue subscription is scoped to that conversation rather than a person’s broader activity.","Cloning copies repository history without following an account.","Pinning a repository customizes a profile rather than follows another person."],concept:"Following people",hints:["Is the interest in one thread or a person’s broader activity?","Which relationship supports staying informed without access escalation?"],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/following-people"},
  {id:"ghf-218",domain:"Explore the GitHub community",prompt:"A learner follows an organization on GitHub. What should they expect from that action?",choices:["Membership in every private team","A way to keep up with the organization’s public activity, not private repository access","Write permission to all organization repositories","A copy of all organization repositories on their computer"],correct:1,explanations:["Following is not team membership.","Following helps surface public activity without granting private access.","Write permission requires a separate grant.","Following does not clone repositories."],concept:"Following organizations",hints:["Does interest imply membership?","Separate activity discovery from authorization."],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/following-organizations"},
  {id:"ghf-219",domain:"Explore the GitHub community",prompt:"A team wants a catalog of integrations and reusable automation that extend GitHub workflows. Which destination is designed for this?",choices:["Only one repository’s workflow run history","Only one project’s issue-template chooser","GitHub Marketplace","Only their personal repository creation form"],correct:2,explanations:["Run history records automation executions rather than a catalog of tools.","Issue templates guide work intake rather than list workflow integrations.","Marketplace helps users discover apps and Actions.","Repository creation options do not provide the integration catalog."],concept:"GitHub Marketplace",hints:["Is the goal a catalog of tools?","Which destination includes both integrations and automation components?"],source:"https://docs.github.com/en/apps/github-marketplace/github-marketplace-overview/about-github-marketplace-for-apps"},
  {id:"ghf-220",domain:"Explore the GitHub community",prompt:"A team finds an appealing third-party app on GitHub Marketplace. What should it evaluate before installing it for work repositories?",choices:["Only whether its listing has attractive screenshots","Only whether another team uses it, ignoring requested access","Only whether it has a free option, ignoring publisher and permissions","The requested permissions, publisher, and suitability for the organization’s needs"],correct:3,explanations:["Screenshots alone do not establish trust or suitability.","Another team’s use does not replace evaluating access for this organization.","Price alone is not an access-risk or suitability assessment.","App installation can grant access, so permissions and provider trust need evaluation."],concept:"Evaluating Marketplace integrations",hints:["What authority might installation grant?","Does discoverability alone prove suitability?"],source:"https://docs.github.com/en/apps/using-github-apps/installing-a-github-app-from-github-marketplace-for-your-organizations"},
  {id:"ghf-221",domain:"Explore the GitHub community",prompt:"A public repository contains useful code but no license. What should a prospective user avoid assuming?",choices:["That public visibility alone grants broad permission to reuse and redistribute the code","That the source can be read on GitHub","That the repository can have issues","That its files may have commit history"],correct:0,explanations:["Public visibility is not a substitute for a license granting reuse rights.","Public source is ordinarily readable, subject to access availability.","Public repositories can use issues.","Git repository files can retain history regardless of licensing."],concept:"Open visibility versus open-source rights",hints:["Does seeing code establish legal reuse terms?","Separate technical accessibility from licensing."],source:"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/licensing-a-repository"},
  {id:"ghf-222",domain:"Explore the GitHub community",prompt:"What is a realistic benefit of participating in an open-source project through GitHub?",choices:["Guaranteed acceptance of every proposed change","Learning from review and collaborating with people beyond one’s own team","Automatic ownership of every dependency","Elimination of the need to follow licenses"],correct:1,explanations:["Maintainers still decide whether changes fit the project.","Contribution can develop skills and relationships through shared work and feedback.","Participation does not transfer ownership of dependencies.","License obligations still apply."],concept:"Benefits of open-source participation",hints:["Which outcomes depend on shared learning rather than guarantees?","Distinguish opportunity from entitlement."],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/finding-ways-to-contribute-to-open-source-on-github"},
  {id:"ghf-223",domain:"Explore the GitHub community",prompt:"An open-source project wants contributors to understand expected behavior and how unacceptable conduct is handled. Which document is intended for this?",choices:["A dependency lockfile","A release tag list","A code of conduct","A branch naming convention alone"],correct:2,explanations:["Lockfiles record dependency resolution.","Tags identify versions.","A code of conduct states community behavior expectations and reporting guidance.","Branch names do not define community conduct or reporting processes."],concept:"Community conduct",hints:["Is the policy about people’s behavior or file versions?","What helps create a respectful participation environment?"],source:"https://docs.github.com/en/communities/setting-up-your-project-for-healthy-contributions/adding-a-code-of-conduct-to-your-project"},
  {id:"ghf-224",domain:"Explore the GitHub community",prompt:"An eligible open-source organization wants to receive financial support through GitHub Sponsors. Which statement about recipient account types is correct?",choices:["Only individuals can receive funds; organizations can only sponsor others","Organizations qualify only if they convert their repositories into personal repositories","Organizations can receive support only by sharing one maintainer’s personal login","Eligible organizations as well as individuals can receive sponsorship"],correct:3,explanations:["Organizations can participate as recipients as well as sponsors when eligible.","Receiving sponsorship does not require converting organization repositories into personal ones.","Shared personal credentials are not the organization sponsorship model.","GitHub Sponsors supports eligible people and organizations."],concept:"Sponsorship recipients",hints:["Can maintenance be organized collectively?","Separate eligibility requirements from account-type assumptions."],source:"https://docs.github.com/en/sponsors/getting-started-with-github-sponsors/about-github-sponsors"},
  {id:"ghf-225",domain:"Explore the GitHub community",prompt:"A learner wants to discover public repositories about climate data across many owners. Which approach is most useful?",choices:["Search relevant repository topics and explore matching projects","Inspect only their own local remotes","Search only the files in one already-cloned repository","Inspect only issues assigned to them in one project"],correct:0,explanations:["Topics and repository search support subject-based discovery across projects.","Local remotes only describe repositories already configured locally.","A single local repository does not provide broad project discovery.","Assigned issues are a narrow personal work subset rather than cross-owner repository discovery."],concept:"Topic-based project discovery",hints:["Where is subject metadata shared across repositories?","Distinguish discovering projects from organizing work already known."],source:"https://docs.github.com/en/get-started/exploring-projects-on-github/finding-ways-to-contribute-to-open-source-on-github"},
];
